// retireSettledImplicationSubproofs — goal-driven payloads, wiped scopes,
// unrelated implications and prepared templates without a scope stay.
TEST(prover, retire_settled_implication_subproofs_ignores_non_candidates) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    gl::EquivalenceClass cls;
    cls.setMembersFromNames({ "a", "b" }, ((m).nameMap));
    m.assignClassesById(gl::NameMap::MAIN_ID, { cls });
    seedFixtureCanonicalClasses(m);
    // Goal-driven subproof of a known implication: follows its goal.
    const gl::NameId goalDriven = openMainSubproof(m, "(fold[x])_subproof_(implication7[a])");
    // Already wiped subproof of a known implication.
    const gl::NameId wiped = openMainSubproof(m, "(implication9[a])");
    ((m).intValidityNamesToFilter).mint(wiped);
    // Open subproofs of two implications that differ beyond the classes.
    openMainSubproof(m, "(implication7[c])");
    openMainSubproof(m, "(implication8[a])");
    // Prepared implication template with no pushed scope.
    ((m).integrationPrepared).mint(gl::mintTemplateKey(
        ((m).templateInterner), ((m).nameMap), std::string("(implication6[a])"), std::string("main")));
    gl::upsertStatementKey(((m).intKnownStatements),
        gl::packStatementKey(((m).nameMap).encode("(implication7[a])"), gl::NameMap::MAIN_ID),
        /*local=*/true, /*fullyDisintegrated=*/false);
    gl::upsertStatementKey(((m).intKnownStatements),
        gl::packStatementKey(((m).nameMap).encode("(implication9[b])"), gl::NameMap::MAIN_ID),
        /*local=*/true, /*fullyDisintegrated=*/false);

    ea.implicationSubproofs.retireSettledImplicationSubproofs(m);

    ASSERT_FALSE(((m).pendingWipeScopes).contains(goalDriven));
    ASSERT_TRUE(((m).pendingWipeScopes).empty());
}

namespace {
    // Opens a bare-payload implication subproof below @p parent the way Case A
    // does: prepared key at the parent, pushed scope.
    gl::NameId openSubproofAt(gl::Memory& m, gl::NameId parent, const std::string& payload) {
        ((m).integrationPrepared).mint(gl::mintTemplateKey(
            ((m).templateInterner), ((m).nameMap), payload, ((m).nameMap).decode(parent)));
        return ((m).nameMap).encodePush(parent, payload);
    }

    // Makes @p text a known statement at @p scope (the registry write only).
    void knowAt(gl::Memory& m, const char* text, gl::NameId scope) {
        gl::upsertStatementKey(((m).intKnownStatements),
            gl::packStatementKey(((m).nameMap).encode(text), scope),
            /*local=*/true, /*fullyDisintegrated=*/false);
    }
}

// retireSettledImplicationSubproofs — a subproof whose implication is refuted
// at its parent or an ancestor, literally or through the parent's classes, is
// queued; a refutation known only in a child scope retires the subproof nested
// there, never the one above it; a primed contradiction block keeps its
// refuted subproofs (D-532).
TEST(prover, retire_settled_implication_subproofs_wipes_refuted_part) {
    gl::tests::ProverFixture ea("Peano");
    {
        gl::Memory m;
        gl::EquivalenceClass cls;
        cls.setMembersFromNames({ "a", "b" }, ((m).nameMap));
        m.assignClassesById(gl::NameMap::MAIN_ID, { cls });
        const gl::NameId refuted = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication7[a])");
        const gl::NameId above = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication8[c])");
        const gl::NameId branch = ((m).nameMap).encodePush(gl::NameMap::MAIN_ID,
            std::string("ordis_(or1[c,d])_((=[c,d]))"));
        const gl::NameId nested = openSubproofAt(m, branch, "(implication8[c])");
        const gl::NameId nestedOpen = openSubproofAt(m, branch, "(implication9[c])");
        seedFixtureCanonicalClasses(m);
        knowAt(m, "!(implication7[b])", gl::NameMap::MAIN_ID);
        knowAt(m, "!(implication8[c])", branch);

        ea.implicationSubproofs.retireSettledImplicationSubproofs(m);

        ASSERT_TRUE(((m).pendingWipeScopes).contains(refuted));
        ASSERT_FALSE(((m).pendingWipeScopes).contains(above));
        ASSERT_TRUE(((m).pendingWipeScopes).contains(nested));
        ASSERT_FALSE(((m).pendingWipeScopes).contains(nestedOpen));
    }
    {
        gl::Memory m;
        m.primedForContradiction = true;
        const gl::NameId refuted = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication7[a])");
        seedFixtureCanonicalClasses(m);
        knowAt(m, "!(implication7[a])", gl::NameMap::MAIN_ID);

        ea.implicationSubproofs.retireSettledImplicationSubproofs(m);

        ASSERT_FALSE(((m).pendingWipeScopes).contains(refuted));
    }
}

// retireSubproofReductios — a reductio scope leaves with its bare implication
// subproof: a queued or closed subproof takes its open reductio along; an open
// subproof keeps it; a reductio already closed is not queued again; a primed
// contradiction block is left alone (D-532).
TEST(prover, retire_subproof_reductios_follow_their_subproofs) {
    gl::tests::ProverFixture ea("Peano");
    const auto reductioOf = [](gl::Memory& m, gl::NameId parent, const std::string& payload) {
        return ((m).nameMap).encodePush(parent, "contradiction_!" + payload);
    };
    {
        gl::Memory m;
        const gl::NameId queued = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication7[a])");
        const gl::NameId queuedReductio = reductioOf(m, gl::NameMap::MAIN_ID, "(implication7[a])");
        const gl::NameId closed = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication8[a])");
        const gl::NameId closedReductio = reductioOf(m, gl::NameMap::MAIN_ID, "(implication8[a])");
        openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication9[a])");
        const gl::NameId openReductio = reductioOf(m, gl::NameMap::MAIN_ID, "(implication9[a])");
        const gl::NameId discharged = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication6[a])");
        const gl::NameId dischargedReductio = reductioOf(m, gl::NameMap::MAIN_ID, "(implication6[a])");
        ((m).pendingWipeScopes).mint(queued);
        ((m).intValidityNamesToFilter).mint(closed);
        ((m).pendingWipeScopes).mint(discharged);
        ((m).intValidityNamesToFilter).mint(dischargedReductio);

        ea.implicationSubproofs.retireSubproofReductios(m);

        ASSERT_TRUE(((m).pendingWipeScopes).contains(queuedReductio));
        ASSERT_TRUE(((m).pendingWipeScopes).contains(closedReductio));
        ASSERT_FALSE(((m).pendingWipeScopes).contains(openReductio));
        ASSERT_FALSE(((m).pendingWipeScopes).contains(dischargedReductio));
        ASSERT_EQ(((m).pendingWipeScopes).count(), 4);
    }
    {
        gl::Memory m;
        m.primedForContradiction = true;
        const gl::NameId queued = openSubproofAt(m, gl::NameMap::MAIN_ID, "(implication7[a])");
        const gl::NameId reductio = reductioOf(m, gl::NameMap::MAIN_ID, "(implication7[a])");
        ((m).pendingWipeScopes).mint(queued);

        ea.implicationSubproofs.retireSubproofReductios(m);

        ASSERT_FALSE(((m).pendingWipeScopes).contains(reductio));
    }
}

namespace {
    // Opens one OR-integration case below @p parent the way Case OR does: the
    // case scope and its disjunct as the goal row there.
    gl::NameId openOrIntegrationCase(gl::Memory& m, gl::NameId parent,
                                     const std::string& payload, const char* goal) {
        const gl::NameId scope = ((m).nameMap).encodePush(parent, payload);
        ((m).intToBeProved).assignSet(
            gl::packStatementKey(((m).nameMap).encode(goal), scope), nullptr, 0);
        return scope;
    }

    // Class {a,b} at main, seen by every scope below it.
    void classAB(gl::Memory& m) {
        gl::EquivalenceClass cls;
        cls.setMembersFromNames({ "a", "b" }, ((m).nameMap));
        m.assignClassesById(gl::NameMap::MAIN_ID, { cls });
    }
}

// retireDuplicateOrIntegrationFamilies — of two open families under one parent
// whose ORs are class-equal there, the one with more statements survives and
// every case of the other is queued (D-550).
TEST(prover, retire_duplicate_or_integration_families_keeps_bigger_family) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    classAB(m);
    const gl::NameId parent = ((m).nameMap).encodePush(gl::NameMap::MAIN_ID, std::string("(implA)"));
    const gl::NameId a1 = openOrIntegrationCase(m, parent, "orint_(or7[a,x])_((in[1,a]))", "(in[1,a])");
    const gl::NameId a2 = openOrIntegrationCase(m, parent, "orint_(or7[a,x])_((in[2,x]))", "(in[2,x])");
    const gl::NameId b1 = openOrIntegrationCase(m, parent, "orint_(or7[b,x])_((in[1,b]))", "(in[1,b])");
    const gl::NameId b2 = openOrIntegrationCase(m, parent, "orint_(or7[b,x])_((in[2,x]))", "(in[2,x])");
    seedFixtureCanonicalClasses(m);
    addScopedStatement(m, "!(in[2,x])", a1);
    addScopedStatement(m, "!(in[2,x])", b1);
    addScopedStatement(m, "!(in[1,b])", b2);
    addScopedStatement(m, "(in[3,b])", b2);

    ea.caseProcessor.retireDuplicateOrIntegrationFamilies(m);

    ASSERT_TRUE(((m).pendingWipeScopes).contains(a1));
    ASSERT_TRUE(((m).pendingWipeScopes).contains(a2));
    ASSERT_FALSE(((m).pendingWipeScopes).contains(b1));
    ASSERT_FALSE(((m).pendingWipeScopes).contains(b2));
    ASSERT_EQ(((m).pendingWipeScopes).count(), 2);
}

