    gl::addOriginEncoded(((m).exprOriginMap), ((m).originInterner), gl::StrSpan(expression),
        gl::StrSpan("main", 4), gl::OriginTag::disintegration, source, 1, 10);
    gl::addOriginEncoded(((m).exprOriginMap), ((m).originInterner), gl::StrSpan(expression),
        gl::StrSpan("main", 4), gl::OriginTag::equality1, source, 1, 10);
