TEST(prover, build_stack_preserves_both_zoom_in_endpoints) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory& m = ea.body;
    const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
    const gl::NameId parentId = ((m).nameMap).encodePush(mainId, std::string("parent_scope"));
    const gl::NameId childId = ((m).nameMap).encodePush(parentId, std::string("child_scope"));
    const std::string parent = ((m).nameMap).decode(parentId);
    const std::string child = ((m).nameMap).decode(childId);
    const std::string expression = "(in[a,N])";
    const int64_t mainKey = gl::mintOriginKey(((m).originInterner), expression, "main");
    const int64_t parentKey = gl::mintOriginKey(((m).originInterner), expression, parent);
    const int64_t childKey = gl::mintOriginKey(((m).originInterner), expression, child);
    const int64_t consumerKey = gl::mintOriginKey(((m).originInterner), "(in[b,N])", child);
    ((m).exprOriginMap).assignRun(mainKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    ((m).exprOriginMap).assignRun(parentKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    ((m).exprOriginMap).assignRun(childKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::zoomIn, {parentKey})});
    ((m).exprOriginMap).assignRun(consumerKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::implication, {childKey})});
    std::vector<std::vector<std::string>> rows;
    std::set<gl::ExpressionWithValidity> covered;
    ASSERT_TRUE(ea.proofReconstructor.buildStack(m, gl::ExpressionWithValidity("(in[b,N])", child), rows, covered));
    const auto zoom = std::find_if(rows.begin(), rows.end(), [](const auto& row) { return row[2] == "zoom in"; });
    ASSERT_TRUE(zoom != rows.end());
    ASSERT_TRUE((*zoom == std::vector<std::string>{expression, child, "zoom in", expression, parent}));
    ASSERT_TRUE(std::any_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row[0] == expression && row[1] == parent;
    }));
    ASSERT_TRUE(std::none_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row[0] == expression && row[1] == "main";
    }));
}

// originScopeAlternatives lists every origin-bearing scope of an expression,
// shallowest first (main, then the subproof), the shallowest being the scope
// liftToShallowestOriginAncestor picks; an expression without records keeps
// its own scope, and an exact zoom-in record pins it.
TEST(prover, origin_scope_alternatives_list_every_origin_scope_shallowest_first) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory& m = ea.body;
    const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
    const gl::NameId subId = ((m).nameMap).encodePush(mainId, std::string("sub_scope"));
    const std::string sub = ((m).nameMap).decode(subId);
    const std::string expression = "(p[a,a])";
    const int64_t mainKey = gl::mintOriginKey(((m).originInterner), expression, "main");
    const int64_t subKey = gl::mintOriginKey(((m).originInterner), expression, sub);
    ((m).exprOriginMap).assignRun(mainKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    ((m).exprOriginMap).assignRun(subKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    const auto both = gl::tests::ProofReconstructorFixture::originScopeAlternatives(m, gl::ExpressionWithValidity(expression, sub));
    ASSERT_EQ(both.size(), static_cast<std::size_t>(2));
    ASSERT_TRUE(both[0] == gl::ExpressionWithValidity(expression, "main"));
    ASSERT_TRUE(both[1] == gl::ExpressionWithValidity(expression, sub));
    const auto none = gl::tests::ProofReconstructorFixture::originScopeAlternatives(m, gl::ExpressionWithValidity("(q[b])", sub));
    ASSERT_EQ(none.size(), static_cast<std::size_t>(1));
    ASSERT_TRUE(none[0] == gl::ExpressionWithValidity("(q[b])", sub));
    const int64_t zoomKey = gl::mintOriginKey(((m).originInterner), "(r[c])", sub);
    const int64_t zoomMainKey = gl::mintOriginKey(((m).originInterner), "(r[c])", "main");
    ((m).exprOriginMap).assignRun(zoomMainKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    ((m).exprOriginMap).assignRun(zoomKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::zoomIn, {zoomMainKey})});
    const auto pinned = gl::tests::ProofReconstructorFixture::originScopeAlternatives(m, gl::ExpressionWithValidity("(r[c])", sub));
    ASSERT_EQ(pinned.size(), static_cast<std::size_t>(1));
    ASSERT_TRUE(pinned[0] == gl::ExpressionWithValidity("(r[c])", sub));
}

// A contradiction scope is a lift barrier for its own assumption: the
// assumption cited at the scope or below it stays at the scope although an
// ancestor holds a record of the same statement; any other statement still
// lifts to the ancestor, the assumption cited outside the scope is not
// affected, and a positive scope product assumes its negation.
TEST(prover, lift_keeps_a_contradiction_assumption_inside_its_scope) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory& m = ea.body;
    const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
    const gl::NameId outerId = ((m).nameMap).encodePush(mainId, std::string("contradiction_!(q[b])"));
    const gl::NameId reductioId = ((m).nameMap).encodePush(outerId, std::string("contradiction_!(r[c])"));
    const gl::NameId innerId = ((m).nameMap).encodePush(reductioId, std::string("sub_scope"));
    const gl::NameId positiveId = ((m).nameMap).encodePush(mainId, std::string("contradiction_(t[e])"));
    const std::string outer = ((m).nameMap).decode(outerId);
    const std::string reductio = ((m).nameMap).decode(reductioId);
    const std::string inner = ((m).nameMap).decode(innerId);
    const std::string positive = ((m).nameMap).decode(positiveId);
    const auto record = [&](const std::string& expression, const std::string& scope) {
        const int64_t key = gl::mintOriginKey(((m).originInterner), expression, scope);
        ((m).exprOriginMap).assignRun(key, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    };
    record("(r[c])", outer);
    record("(r[c])", reductio);
    record("(s[d])", outer);
    record("(s[d])", reductio);
    record("!(t[e])", "main");
    record("!(t[e])", positive);
    record("(t[e])", "main");
    record("(t[e])", positive);
    using Fixture = gl::tests::ProofReconstructorFixture;
    ASSERT_TRUE(Fixture::liftToShallowestOriginAncestor(m, gl::ExpressionWithValidity("(r[c])", reductio))
        == gl::ExpressionWithValidity("(r[c])", reductio));
    ASSERT_TRUE(Fixture::liftToShallowestOriginAncestor(m, gl::ExpressionWithValidity("(r[c])", inner))
        == gl::ExpressionWithValidity("(r[c])", reductio));
    ASSERT_TRUE(Fixture::liftToShallowestOriginAncestor(m, gl::ExpressionWithValidity("(s[d])", reductio))
        == gl::ExpressionWithValidity("(s[d])", outer));
    ASSERT_TRUE(Fixture::liftToShallowestOriginAncestor(m, gl::ExpressionWithValidity("(r[c])", outer))
        == gl::ExpressionWithValidity("(r[c])", outer));
    ASSERT_TRUE(Fixture::liftToShallowestOriginAncestor(m, gl::ExpressionWithValidity("!(t[e])", positive))
        == gl::ExpressionWithValidity("!(t[e])", positive));
    ASSERT_TRUE(Fixture::liftToShallowestOriginAncestor(m, gl::ExpressionWithValidity("(t[e])", positive))
        == gl::ExpressionWithValidity("(t[e])", "main"));
    const auto alternatives = Fixture::originScopeAlternatives(m, gl::ExpressionWithValidity("(r[c])", inner));
    ASSERT_EQ(alternatives.size(), static_cast<std::size_t>(1));
    ASSERT_TRUE(alternatives[0] == gl::ExpressionWithValidity("(r[c])", reductio));
}

// buildStack: a row inside a reductio scope that cites the scope's assumption
// keeps that citation at the scope, so the reductio's contradiction reaches
// its own assumption even when the parent scope proves the same statement.
TEST(prover, build_stack_cites_a_reductio_assumption_at_its_scope) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory& m = ea.body;
    const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
    const gl::NameId parentId = ((m).nameMap).encodePush(mainId, std::string("parent_scope"));
    const gl::NameId reductioId = ((m).nameMap).encodePush(parentId, std::string("contradiction_!(r[c])"));
    const std::string parent = ((m).nameMap).decode(parentId);
    const std::string reductio = ((m).nameMap).decode(reductioId);
    const int64_t parentCopyKey = gl::mintOriginKey(((m).originInterner), "(r[c])", parent);
    const int64_t assumptionKey = gl::mintOriginKey(((m).originInterner), "(r[c])", reductio);
    const int64_t consumerKey = gl::mintOriginKey(((m).originInterner), "(m[x])", reductio);
    ((m).exprOriginMap).assignRun(parentCopyKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    ((m).exprOriginMap).assignRun(assumptionKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    ((m).exprOriginMap).assignRun(consumerKey, std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::implication, {assumptionKey})});
    std::vector<std::vector<std::string>> rows;
    std::set<gl::ExpressionWithValidity> covered;
    ASSERT_TRUE(ea.proofReconstructor.buildStack(m, gl::ExpressionWithValidity("(m[x])", reductio), rows, covered));
    ASSERT_TRUE(std::any_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row == std::vector<std::string>{"(m[x])", reductio, "implication", "(r[c])", reductio};
    }));
    ASSERT_TRUE(std::any_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row == std::vector<std::string>{"(r[c])", reductio, "task formulation"};
    }));
    ASSERT_TRUE(std::none_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row[0] == "(r[c])" && row[1] == parent;
    }));
}

namespace {
// A subproof proves the implication R through its goal H, which follows by
// equality from P at the subproof. P's subproof record derives it from
// `subproofDependency`; P's main record from `mainDependencies`.
struct DeeperCopyFixture {
    gl::tests::ProverFixture ea{"Peano"};
    gl::Memory& m = ea.body;
    std::string sub;

    DeeperCopyFixture(const std::vector<std::string>& subproofDependency,
                      const std::vector<std::string>& mainDependencies) {
        const gl::NameId mainId = m.nameMap.encode(std::string("main"));
        sub = m.nameMap.decode(m.nameMap.encodePush(mainId, std::string("sub_scope")));
        const auto key = [&](const std::string& expression) {
            return gl::mintOriginKey(m.originInterner, expression, expression == "(R[a])" || expression == "(F[a])" ? "main" : sub);
        };
        const auto keys = [&](const std::vector<std::string>& expressions) {
            std::vector<int64_t> result;
            for (const std::string& expression : expressions) result.push_back(key(expression));
            return result;
        };
        const int64_t pMain = gl::mintOriginKey(m.originInterner, "(P[a,a])", "main");
        m.exprOriginMap.assignRun(key("(R[a])"), std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::validityName, {key("(H[a,x])")})});
        m.exprOriginMap.assignRun(key("(H[a,x])"), std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::equality1, {key("(P[a,a])"), key("(=[a,x])")})});
        m.exprOriginMap.assignRun(key("(=[a,x])"), std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
        m.exprOriginMap.assignRun(key("(P[a,a])"), std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::implication, keys(subproofDependency))});
        m.exprOriginMap.assignRun(pMain, std::vector<gl::IdOrigin>{mainDependencies.empty()
            ? gl::IdOrigin(gl::OriginTag::taskFormulation, {})
            : gl::IdOrigin(gl::OriginTag::implication, keys(mainDependencies))});
        m.exprOriginMap.assignRun(key("(F[a])"), std::vector<gl::IdOrigin>{gl::IdOrigin(gl::OriginTag::taskFormulation, {})});
    }

    bool plainWalk(std::vector<std::vector<std::string>>& rows) {
        std::set<gl::ExpressionWithValidity> covered;
        ea.proofReconstructor.beginRootTraversal();
        return ea.proofReconstructor.buildStack(m, gl::ExpressionWithValidity("(R[a])", "main"), rows, covered);
    }

    bool chapterWalk(std::vector<std::vector<std::string>>& rows) {
        std::set<gl::ExpressionWithValidity> covered;
        return ea.proofReconstructor.buildChapterStack(m, gl::ExpressionWithValidity("(R[a])", "main"), rows, covered);
    }

    std::string equalityCitationScope(const std::vector<std::vector<std::string>>& rows) const {
        const auto row = std::find_if(rows.begin(), rows.end(), [](const auto& r) { return r[2] == "equality1"; });
        assert(row != rows.end() && (*row)[3] == "(P[a,a])");
        return (*row)[4];
    }
};
}

// P also holds at main, but only through R itself: lifting P to main closes a
// cycle, so the shallowest-scope walk fails, and the chapter walk's retry
// cites P at the subproof, where its own record derives it from a main fact.
TEST(prover, chapter_stack_cites_the_deeper_copy_when_the_shallow_copy_closes_a_cycle) {
    DeeperCopyFixture f({"(F[a])"}, {"(R[a])", "(F[a])"});
    std::vector<std::vector<std::string>> plain;
    ASSERT_FALSE(f.plainWalk(plain));
    std::vector<std::vector<std::string>> rows;
    ASSERT_TRUE(f.chapterWalk(rows));
    ASSERT_TRUE(f.equalityCitationScope(rows) == f.sub);
    ASSERT_TRUE(std::any_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row[0] == "(P[a,a])" && row[1] == f.sub && row[2] == "implication";
    }));
    ASSERT_TRUE(std::none_of(rows.begin(), rows.end(), [&](const auto& row) {
        return row[0] == "(P[a,a])" && row[1] == "main";
    }));
}

// A chapter the shallowest-scope walk resolves is emitted unchanged: P is
// cited at main, although the subproof also holds an acyclic copy.
TEST(prover, chapter_stack_keeps_a_chapter_the_shallowest_walk_resolves) {
    DeeperCopyFixture f({"(F[a])"}, {});
    std::vector<std::vector<std::string>> plain;
    ASSERT_TRUE(f.plainWalk(plain));
    std::vector<std::vector<std::string>> rows;
    ASSERT_TRUE(f.chapterWalk(rows));
    ASSERT_TRUE(rows == plain);
    ASSERT_TRUE(f.equalityCitationScope(rows) == "main");
}

// When no scope choice resolves the cycle (P's subproof copy needs R too),
// the retry fails and the chapter keeps the first walk's degraded rows.
TEST(prover, chapter_stack_keeps_the_first_walk_when_no_scope_resolves_the_cycle) {
    DeeperCopyFixture f({"(R[a])"}, {"(R[a])", "(F[a])"});
    std::vector<std::vector<std::string>> plain;
    ASSERT_FALSE(f.plainWalk(plain));
    std::vector<std::vector<std::string>> rows;
    ASSERT_FALSE(f.chapterWalk(rows));
    ASSERT_TRUE(rows == plain);
    ASSERT_FALSE(rows.empty());
}

namespace {
struct SourceReplayFixture {
    gl::tests::ProverFixture analyzer{"Peano"};
    gl::Memory memory;
    gl::ScratchArena& arena = gl::genScratchArenas().forSlot(gl::genScratchArenas().slotCount()-1);
    std::string source = "(existence96[1,2,3,4])";
    std::string marker = "(in3[2,3,marker,4])";
    int levels[2] = {0, 2};
    SourceReplayFixture() {
        gl::CompiledDefinitionFixture::operators(analyzer.definitions).clear();
        gl::CompiledDefinitionFixture::operators(analyzer.definitions).insert("in3");
        gl::CompiledDefinitionFixture::compiledExpressions(analyzer.definitions)["existence96"] = gl::LogicalEntity("existence",
            {"(in[w,u_1])", "(in3[u_2,u_3,w,u_4])"},
            "(existence96[u_1,u_2,u_3,u_4])", 4);
        analyzer.supportingRuleCompiler.compileDisintegrationPackages();
        analyzer.parameters.trackHistory = true;
        ((memory).level) = 2;
        ((memory).nameMap).encode("main");
    }
    std::string child(const char* name = "child") {
        const auto scope = ((memory).nameMap).encodePush(gl::NameMap::MAIN_ID, name);
        analyzer.canonicalizer.initializeCanonicalScope(memory, scope);
        return ((memory).nameMap).decode(scope);
    }
    void demand(const std::string& scope, bool integration = false, bool tagged = false) {
        const int64_t key = gl::mintTemplateKey(((memory).templateInterner), ((memory).nameMap), marker, scope);
        if (integration) ((((memory).overallHashMemory)).admissionSetIntegration).mint(key);
        else {
            gl::AdmissionMapValue value;
            value.standardMaxAdmissionDepth = analyzer.parameters.maxIterationNumberVariable;
            value.standardMaxSecondaryNumber = analyzer.parameters.maxNumberSecondaryVariables;
            value.ordisOnly = tagged;
            value.key = {((memory).valueInterner).encode("(in3[8,9,10,11])")};
            gl::insertAdmissionValue(((((memory).overallHashMemory)).admissionMap), key, value, ((memory).valueInterner), arena);
            ((((memory).overallHashMemory)).admissionStatusMap).upsert(key, uint8_t(0));
        }
    }
    // The induction hypothesis's chain (recursion-owned, "admitted by
    // induction hypothesis", induction budgets) on marker template `templ` at
    // `scope`, premise chain `chain` with sorted remaining arguments
    // `remaining`; the template's status becomes 1. `hypothesis` false files
    // a recursion-owned value without the hypothesis bit, as the goal door's
    // demand is.
    void inductionDemandAt(const std::string& templ, const std::string& scope,
                           const std::vector<std::string>& chain,
                           const std::vector<std::string>& remaining, bool hypothesis = true) {
        const int64_t key = gl::mintTemplateKey(((memory).templateInterner), ((memory).nameMap), templ, scope);
        gl::AdmissionMapValue value;
        value.standardMaxAdmissionDepth = analyzer.parameters.maxIterationNumberVariable;
        value.standardMaxSecondaryNumber = analyzer.parameters.maxNumberSecondaryVariables;
        value.flag = true;
        value.inductionHypothesis = hypothesis;
        for (const std::string& element : chain) value.key.push_back(((memory).valueInterner).encode(element));
        for (const std::string& argument : remaining)
            value.remainingArgs.push_back(((memory).valueInterner).encode(argument));
        gl::insertAdmissionValue(((((memory).overallHashMemory)).admissionMap), key, value, ((memory).valueInterner), arena);
        ((((memory).overallHashMemory)).admissionStatusMap).upsert(key, uint8_t(1));
    }
    // The induction hypothesis's chain on the fixture's marker template.
    void inductionDemand(const std::string& scope, const std::vector<std::string>& chain,
                         const std::vector<std::string>& remaining, bool hypothesis = true) {
        inductionDemandAt(marker, scope, chain, remaining, hypothesis);
    }
    void deposit() {
        depositAt(source, "main");
    }
    void depositAt(const std::string& text, const std::string& scope) {
        analyzer.statementMemory.addExprToMemoryBlock(gl::StrSpan(text), memory, 0, 1, levels, 2,
            gl::TransientOrigin{true, gl::OriginTag::taskFormulation, nullptr, 0},
            -1, -1, gl::StrSpan(scope), false);
    }
    bool demandFiled(const std::string& templ, const std::string& scopeName = "main") {
        const gl::NameId text = ((memory).templateInterner).lookup(gl::StrSpan(templ));
        const gl::NameId scope = ((memory).nameMap).lookup(gl::StrSpan(scopeName));
        return text != 0 && scope != 0 && ((((memory).overallHashMemory)).admissionMap).lookup(
            gl::packInt32Pair(text, scope)) != 0;
    }
    // The block's induction scopes in id order, decoded
    // (D-519).
    std::vector<std::string> inductionScopes() {
        std::vector<std::string> out;
        for (gl::NameId id = 1; id <= ((memory).nameMap).nameCount(); ++id)
            if (gl::ScopeSyntax::isInductionScope((memory).nameMap, id))
                out.push_back(((memory).nameMap).decode(id));
        return out;
    }
    bool known(const std::string& statement, const std::string& scope) {
        return gl::lookupStatementFlags(((memory).intKnownStatements), ((memory).nameMap),
            gl::StrSpan(statement), gl::StrSpan(scope)) != nullptr;
    }
    int64_t park(bool integration = false, const std::string& scope = "main", int generation = 0, int depth = 0) {
        if (integration) analyzer.rejectedSources.updateRejectedMapIntegration(gl::StrSpan(marker), gl::StrSpan(source),
            generation, 2, levels, 2, ((memory).overallHashMemory), memory, gl::StrSpan(scope), nullptr, 0, depth);
        else analyzer.rejectedSources.updateRejectedMap(gl::StrSpan(marker), gl::StrSpan(source),
            generation, 1, levels, 2, ((memory).overallHashMemory), memory, gl::StrSpan(scope), nullptr, 0, depth);
        return gl::mintTemplateKey(((memory).templateInterner), ((memory).nameMap), marker, scope);
    }
    void wake(const std::string& scope, bool integration = false) {
        if (integration) analyzer.rejectedSourceReplay.revisitRejectedIntegration2(gl::StrSpan(marker), memory, gl::StrSpan(scope));
        else analyzer.rejectedSourceReplay.revisitRejected2(gl::StrSpan(marker), memory, gl::StrSpan(scope));
    }
    void absorb() {
        analyzer.logicBlockOperations.standardProcessing(memory, nullptr, ((memory).sameIterationInternalMail),
            ((memory).nextIterationInternalMail), -1);
    }
};
}

TEST(prover, source_rejection_consumes_no_permanent_witness_or_history) {
    SourceReplayFixture f;
    gl::DisintProducts output(&f.arena);
    const int start = ((f.memory).startInt);
    f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
        gl::StrSpan("main",4), output, true, false, f.levels, 2, true);
    ASSERT_EQ(((f.memory).startInt), start);
    ASSERT_TRUE(((f.memory).exprOriginMap).empty());
    ASSERT_TRUE(((f.memory).mailOut).origins_.empty());
    ASSERT_TRUE(!((((f.memory).overallHashMemory)).rejectedMap).empty());
    ASSERT_TRUE(!((((f.memory).overallHashMemory)).rejectedMapIntegration).empty());
    output.statements.forEachSorted([&](gl::StrSpan text, gl::StrSpan) {
        ASSERT_FALSE(gl::containsSpan(text, gl::StrSpan("__gl_temporary_witness_",23)));
    });
}

TEST(prover, canonical_maintenance_coalesces_wakes_until_sources_and_demands_settle) {
    SourceReplayFixture f;
    const std::string child=f.child();
    const auto scope=((f.memory).nameMap).lookup(child);
    f.park(false); f.park(true);
    f.demand(child,false); f.demand(child,true);
    auto& pending=((f.memory).lbMemory).canonicalUses;
    ASSERT_FALSE(gl::tests::RejectedSourceReplayFixture::queueCanonicalWake(f.analyzer.rejectedSourceReplay, f.memory,gl::StrSpan(f.marker),gl::StrSpan(child),1));
    pending.deferWakes=true;
    for(int i=0;i<4;++i) { f.wake(child,false); f.wake(child,true); }
    f.analyzer.rejectedSourceReplay.revisitRejectedOrdis(gl::StrSpan(f.marker),f.memory,gl::StrSpan(child));
    f.analyzer.rejectedSourceReplay.revisitRejectedOrdis2(gl::StrSpan(f.marker),f.memory,gl::StrSpan(child));
    ASSERT_EQ(pending.wakeKinds.count(),1);
    ASSERT_EQ(*pending.wakeKinds.find(pending.wakeKinds.keyAt(1)),15);
    ASSERT_TRUE(((f.memory).sameIterationInternalMail).statements_.empty());
    ASSERT_TRUE(((f.memory).existenceReplays).empty());
    gl::DirtyState dirty=gl::DirtyState::Clean;
    gl::ColdHashSet<gl::BytesKeyStore> parks(&f.arena,&dirty),empty(&f.arena,&dirty);
    parks.mint(gl::StrSpan(f.marker));
    f.analyzer.rejectedSourceReplay.wakeParkedExistencesAtExistingDemands(f.memory,parks,empty);
    ASSERT_EQ(pending.algebraWakeParks.count(),1);
    ASSERT_TRUE(((f.memory).sameIterationInternalMail).statements_.empty());
    f.analyzer.rejectedSourceReplay.drainCanonicalWakes(f.memory);
    ASSERT_FALSE(pending.deferWakes);
    ASSERT_TRUE(pending.wakeKinds.empty() && pending.algebraWakeParks.empty());
    const auto original=f.analyzer.rejectedSources.canonicalExistenceId(f.memory,gl::StrSpan(f.source),scope);
    ASSERT_EQ(f.analyzer.rejectedSources.existenceStateAt(f.memory,original,scope)&12,12);
    ASSERT_FALSE(((f.memory).sameIterationInternalMail).statements_.empty());
    const int count=((f.memory).sameIterationInternalMail).statements_.count();
    f.wake(child,false); f.wake(child,true);
    ASSERT_EQ(((f.memory).sameIterationInternalMail).statements_.count(),count);
}

TEST(prover, true_class_admission_matches_ancestor_sources_in_both_arrival_orders) {
    for(bool integration:{false,true}) for(bool demandFirst:{false,true}) {
        SourceReplayFixture f;
        f.analyzer.parameters.trackHistory=false;
        const std::string child=f.child();
        const auto childId=((f.memory).nameMap).lookup(child);
        gl::EquivalenceClass parent,local;
        parent.setMembersFromNames({"a","z"},((f.memory).nameMap));
        local.setMembersFromNames({"b","z"},((f.memory).nameMap));
        f.memory.assignClassesById(gl::NameMap::MAIN_ID,{parent});
        f.memory.assignClassesById(childId,{local});
        f.analyzer.equivalenceProcessor.refreshCanonicalClasses(f.memory,gl::NameMap::MAIN_ID);
        if(demandFirst) { f.marker="(in3[a,3,marker,4])"; f.demand(child,integration); }
        f.source="(existence96[1,b,3,4])"; f.marker="(in3[b,3,marker,4])";
        const auto park=f.park(integration);
        if(demandFirst) {
            gl::DirtyState dirty=gl::DirtyState::Clean;
            gl::ColdHashSet<gl::BytesKeyStore> parks(&f.arena,&dirty),empty(&f.arena,&dirty);
            parks.mint(gl::StrSpan(f.marker));
            f.analyzer.rejectedSourceReplay.wakeParkedExistencesAtExistingDemands(f.memory,integration?empty:parks,integration?parks:empty);
        } else {
            f.marker="(in3[a,3,marker,4])"; f.demand(child,integration); f.wake(child,integration);
        }
        ASSERT_FALSE(((f.memory).sameIterationInternalMail).statements_.empty());
        f.absorb();
        ASSERT_EQ(((f.memory).startInt),1);
        ASSERT_TRUE(integration ? ((((f.memory).overallHashMemory)).rejectedMapIntegration).lookup(park)!=0
                               : ((((f.memory).overallHashMemory)).rejectedMap).lookup(park)!=0);
        f.marker="(in3[a,3,marker,4])"; f.wake(child,integration);
        ASSERT_TRUE(((f.memory).sameIterationInternalMail).statements_.empty());
    }
}

// Route 5 (D-492): a double-marker key at main
// admits the integration slot of a source expanded in a child scope when the
// constituent fixes the key's other positions. One algebra-witness input
// leaves the slot to route 5 (a miss parks it); without a visible key
// predicate, or with two algebra inputs, it stays disabled (I-268).
TEST(prover, double_marker_route_admits_below_the_key_and_relaxes_one_algebra_input) {
    struct Case { const char* source; const char* key; bool admitted; bool parked; };
    const Case cases[] = {
        { "(existence96[1,2,3,4])", "(in3[marker1,u_3,marker2,u_4])", true, false },
        { "(existence96[1,2,3,4])", "(in3[marker1,u_9,marker2,u_4])", false, true },
        { "(existence96[1,it_0_lev_1_5,3,4])", "(in3[marker1,u_3,marker2,u_4])", true, false },
        { "(existence96[1,it_0_lev_1_5,3,4])", "(in3[marker1,u_9,marker2,u_4])", false, true },
        { "(existence96[1,it_0_lev_1_5,3,4])", "(in2[marker1,u_3,marker2])", false, false },
        { "(existence96[1,it_0_lev_1_5,it_0_lev_1_6,4])",
          "(in3[marker1,u_it_0_lev_1_6,marker2,u_4])", false, false },
    };
    for (const Case& c : cases) {
        SourceReplayFixture f;
        f.analyzer.parameters.trackHistory = false;
        f.source = c.source;
        const std::string child = f.child();
        const gl::NameId childId = ((f.memory).nameMap).lookup(child);
        ((((f.memory).overallHashMemory)).admissionMapIntegrationDouble).insert(
            gl::mintTemplateKey(((f.memory).templateInterner), ((f.memory).nameMap), c.key, "main"), int64_t(0));
        gl::DisintProducts output(&f.arena);
        f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
            gl::StrSpan(child), output, true, false, f.levels, 2, true);
        const gl::NameId original = f.analyzer.rejectedSources.canonicalExistenceId(f.memory,
            gl::StrSpan(f.source), childId);
        ASSERT_EQ((f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2) != 0, c.admitted);
        ASSERT_EQ(!((((f.memory).overallHashMemory)).rejectedMapIntegration).empty(), c.parked);
    }
}

// A double-marker key filed after a one-algebra-input source parked revives
// the park below it; the replay rechecks the I-268 gate and admits through
// route 5.
TEST(prover, double_marker_key_revives_a_descendant_park) {
    SourceReplayFixture f;
    f.analyzer.parameters.trackHistory = false;
    f.source = "(existence96[1,it_0_lev_1_5,3,4])";
    const std::string child = f.child();
    const gl::NameId childId = ((f.memory).nameMap).lookup(child);
    auto& keys = ((((f.memory).overallHashMemory)).admissionMapIntegrationDouble);
    // A key of another shape makes the predicate visible: the slot parks.
    keys.insert(gl::mintTemplateKey(((f.memory).templateInterner), ((f.memory).nameMap),
        "(in3[marker1,u_9,marker2,u_4])", "main"), int64_t(0));
    gl::DisintProducts output(&f.arena);
    f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
        gl::StrSpan(child), output, true, false, f.levels, 2, true);
    const gl::NameId original = f.analyzer.rejectedSources.canonicalExistenceId(f.memory,
        gl::StrSpan(f.source), childId);
    ASSERT_EQ(f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2, 0);
    ASSERT_FALSE(((((f.memory).overallHashMemory)).rejectedMapIntegration).empty());
    ASSERT_TRUE(((f.memory).sameIterationInternalMail).statements_.empty());

    const std::string key = "(in3[marker1,u_3,marker2,u_4])";
    keys.insert(gl::mintTemplateKey(((f.memory).templateInterner), ((f.memory).nameMap), key, "main"), int64_t(0));
    f.analyzer.rejectedSourceReplay.revisitRejectedIntegrationDouble(f.memory, gl::StrSpan(key),
        gl::StrSpan("main", 4));
    ASSERT_FALSE(((f.memory).sameIterationInternalMail).statements_.empty());
    f.absorb();
    ASSERT_TRUE((f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2) != 0);
}

// The strong step's induction demand (`Memory::inductionDoubleKey`) admits
// through route 5 only for an original whose arguments are numbers outside
// the block's refused lemma digits (`rec` refused too); a refused source
// parks. The same key as a goal key admits either way: an anchor copy, one
// algebra-witness input through the I-268 exception, and a refused digit
// (D-502, D-492). The demand also refuses an original whose input
// (`existence96`'s `in3` inputs, here 2 and 3) is no induction variable of
// the lemma (D-601).
TEST(prover, induction_double_key_admits_only_lemma_input_originals) {
    struct Case { const char* source; bool induction; bool refuseTwo; bool twoInduction; bool admitted; };
    const Case cases[] = {
        { "(existence96[1,2,3,4])", true, false, true, true },
        { "(existence96[1,2,3,4])", true, true, true, false },
        { "(existence96[1,2,3,4])", true, false, false, false },
        { "(existence96[1,rec,3,4])", true, false, true, false },
        { "(existence96[1,x2,3,4])", true, false, true, false },
        { "(existence96[1,it_0_lev_1_5,3,4])", true, false, true, false },
        { "(existence96[1,x2,3,4])", false, false, true, true },
        { "(existence96[1,it_0_lev_1_5,3,4])", false, false, true, true },
        { "(existence96[1,2,3,4])", false, true, true, true },
    };
    for (const Case& c : cases) {
        SourceReplayFixture f;
        f.analyzer.parameters.trackHistory = false;
        f.source = c.source;
        const std::string child = f.child();
        const gl::NameId childId = ((f.memory).nameMap).lookup(child);
        const int64_t key = gl::mintTemplateKey(((f.memory).templateInterner), ((f.memory).nameMap),
            "(in3[marker1,u_3,marker2,u_4])", "main");
        ((((f.memory).overallHashMemory)).admissionMapIntegrationDouble).insert(key, int64_t(0));
        if (c.induction) {
            // The demand and its marked chain are filed together
            // (D-519).
            (f.memory).inductionDoubleKey = key;
            (f.memory).inductionDoubleChainId =
                ((f.memory).nameMap).encode(std::string("(in3[marker1,u_3,marker2,u_4])"));
            // The lemma's induction variables: 3, and 2 unless the case
            // takes it as a constant.
            (f.memory).inductionVariableDigits[(f.memory).inductionVariableDigitCount++] = 3;
            if (c.twoInduction)
                (f.memory).inductionVariableDigits[(f.memory).inductionVariableDigitCount++] = 2;
        }
        if (c.refuseTwo) {
            (f.memory).inductionParameterDigits[0] = 2;
            (f.memory).inductionParameterDigitCount = 1;
        }
        gl::DisintProducts output(&f.arena);
        f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
            gl::StrSpan(child), output, true, false, f.levels, 2, true);
        const gl::NameId original = f.analyzer.rejectedSources.canonicalExistenceId(f.memory,
            gl::StrSpan(f.source), childId);
        ASSERT_EQ((f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2) != 0, c.admitted);
        ASSERT_EQ(!((((f.memory).overallHashMemory)).rejectedMapIntegration).empty(), !c.admitted);
    }
}

// Filed after a source parked, the induction demand wakes it only when its
// arguments are numbers outside the refused lemma digits
// (D-502): `existence96[1,2,3,4]` replays and
// admits; with 2 refused, and `existence96[1,x2,3,4]` or
// `existence96[1,rec,3,4]`, the source stays parked; so it does when its
// input 2 is no induction variable of the lemma
// (D-601).
TEST(prover, induction_double_key_wakes_only_lemma_input_sources) {
    struct Case { const char* source; bool refuseTwo; bool twoInduction; bool numbers; };
    const Case cases[] = {
        { "(existence96[1,2,3,4])", false, true, true },
        { "(existence96[1,2,3,4])", true, true, false },
        { "(existence96[1,2,3,4])", false, false, false },
        { "(existence96[1,x2,3,4])", false, true, false },
        { "(existence96[1,rec,3,4])", false, true, false },
    };
    for (const Case& c : cases) {
        const bool numbers = c.numbers;
        SourceReplayFixture f;
        f.analyzer.parameters.trackHistory = false;
        f.source = c.source;
        const std::string child = f.child();
        const gl::NameId childId = ((f.memory).nameMap).lookup(child);
        gl::DisintProducts output(&f.arena);
        f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
            gl::StrSpan(child), output, true, false, f.levels, 2, true);
        const gl::NameId original = f.analyzer.rejectedSources.canonicalExistenceId(f.memory,
            gl::StrSpan(f.source), childId);
        ASSERT_EQ(f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2, 0);
        ASSERT_FALSE(((((f.memory).overallHashMemory)).rejectedMapIntegration).empty());
        ASSERT_TRUE(((f.memory).sameIterationInternalMail).statements_.empty());

        const std::string key = "(in3[marker1,u_3,marker2,u_4])";
        const int64_t packed = gl::mintTemplateKey(((f.memory).templateInterner), ((f.memory).nameMap), key, "main");
        ((((f.memory).overallHashMemory)).admissionMapIntegrationDouble).insert(packed, int64_t(0));
        (f.memory).inductionDoubleKey = packed;
        (f.memory).inductionDoubleChainId = ((f.memory).nameMap).encode(key);
        (f.memory).inductionVariableDigits[(f.memory).inductionVariableDigitCount++] = 3;
        if (c.twoInduction)
            (f.memory).inductionVariableDigits[(f.memory).inductionVariableDigitCount++] = 2;
        if (c.refuseTwo) {
            (f.memory).inductionParameterDigits[0] = 2;
            (f.memory).inductionParameterDigitCount = 1;
        }
        f.analyzer.rejectedSourceReplay.revisitRejectedIntegrationDouble(f.memory, gl::StrSpan(key),
            gl::StrSpan("main", 4));
        ASSERT_EQ(((f.memory).sameIterationInternalMail).statements_.empty(), !numbers);
        if (!numbers) continue;
        f.absorb();
        ASSERT_TRUE((f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2) != 0);
    }
}

// D1's shape, `exists r: exists t: (t linked to r) and exists p: r + p = b`:
// the strong step's demand matches only the innermost p, and its route-5
// hit brings the enclosing t and r along when the path's facts link them
// (`in3[r,p,b,+]`, `in2[t,r,+]`); with t unlinked (`in2[t,a,+]`) p waits,
// nothing is minted and the top source parks
// (D-501).
TEST(prover, double_marker_hit_brings_linked_enclosing_witnesses_along) {
    for (const bool linked : { true, false }) {
        SourceReplayFixture f;
        f.analyzer.parameters.trackHistory = false;
        auto& compiled = gl::CompiledDefinitionFixture::compiledExpressions(f.analyzer.definitions);
        compiled["existence97"] = gl::LogicalEntity("existence",
            {"(in[r,u_1])", "(existence98[u_1,u_2,r,u_3,u_4])"}, "(existence97[u_1,u_2,u_3,u_4])", 4);
        compiled["existence98"] = gl::LogicalEntity("existence",
            {"(in[t,u_1])", linked ? "(in2[t,u_3,u_2])" : "(in2[t,u_4,u_2])", "(existence99[u_1,u_2,u_3,u_5])"},
            "(existence98[u_1,u_2,u_3,u_4,u_5])", 5);
        compiled["existence99"] = gl::LogicalEntity("existence",
            {"(in[p,u_1])", "(in3[u_3,p,u_4,u_2])"}, "(existence99[u_1,u_2,u_3,u_4])", 4);
        f.analyzer.supportingRuleCompiler.compileDisintegrationPackages();
        f.source = "(existence97[1,4,9,10])";
        const std::string child = f.child();
        const gl::NameId childId = ((f.memory).nameMap).lookup(child);
        const int64_t key = gl::mintTemplateKey(((f.memory).templateInterner), ((f.memory).nameMap),
            "(in3[marker1,marker2,u_10,u_4])", "main");
        ((((f.memory).overallHashMemory)).admissionMapIntegrationDouble).insert(key, int64_t(0));
        (f.memory).inductionDoubleKey = key;
        (f.memory).inductionDoubleChainId =
            ((f.memory).nameMap).encode(std::string("(in3[marker1,marker2,u_10,u_4])"));
        // The lemma's induction variables a = 9 and b = 10.
        (f.memory).inductionVariableDigits[0] = 9;
        (f.memory).inductionVariableDigits[1] = 10;
        (f.memory).inductionVariableDigitCount = 2;
        const int initial = ((f.memory).startInt);
        gl::DisintProducts output(&f.arena);
        f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
            gl::StrSpan(child), output, true, false, f.levels, 2, true);
        const gl::NameId original = f.analyzer.rejectedSources.canonicalExistenceId(f.memory,
            gl::StrSpan(f.source), childId);
        ASSERT_EQ((f.analyzer.rejectedSources.existenceStateAt(f.memory, original, childId) & 2) != 0, linked);
        if (!linked) {
            ASSERT_EQ(((f.memory).startInt), initial);
            ASSERT_FALSE(((((f.memory).overallHashMemory)).rejectedMapIntegration).empty());
            ASSERT_TRUE(f.inductionScopes().empty());
            continue;
        }
        // r, t and p are minted; the facts that link them are published in
        // the induction scope the strong demand opened below the child,
        // named by r and p in marker order (D-519).
        ASSERT_TRUE(((f.memory).startInt) >= initial + 3);
        const std::vector<std::string> scopes = f.inductionScopes();
        ASSERT_EQ(scopes.size(), static_cast<std::size_t>(1));
        const std::string prefix = child + "_boundary_is_(in3[marker1,marker2,u_10,u_4])_int_";
        ASSERT_TRUE(scopes[0].compare(0, prefix.size(), prefix) == 0);
        bool step = false, link = false;
        output.statements.forEachSorted([&](gl::StrSpan text, gl::StrSpan validity) {
            const std::string s(text.ptr, static_cast<std::size_t>(text.len));
            const std::string v(validity.ptr, static_cast<std::size_t>(validity.len));
            if (s.rfind("(in3[int_", 0) == 0 && s.find(",10,4])") != std::string::npos) {
                step = true;
                ASSERT_TRUE(v == scopes[0]);
            }
            if (s.rfind("(in2[int_", 0) == 0 && s.find(",int_") != std::string::npos) {
                link = true;
                ASSERT_TRUE(v == scopes[0]);
            }
        });
        ASSERT_TRUE(step);
        ASSERT_TRUE(link);
    }
}

// A parked source replayed into a descendant scope ships its zoom in row on
// the outgoing mail as well: descendant blocks receive what is derived from it
// and must resolve its citation there (I-64 exception).
TEST(prover, source_replay_ships_its_zoom_in_row_to_the_outgoing_mail) {
    SourceReplayFixture f;
    const std::string child = f.child();
    f.park(true, "main", 0, 0);
    f.demand(child, true);
    ASSERT_TRUE(((f.memory).mailOut).origins_.empty());
    f.wake(child, true);
    ASSERT_FALSE(((f.memory).sameIterationInternalMail).statementsEmpty());
    int64_t key = 0;
    ASSERT_TRUE(gl::lookupOriginKey(((f.memory).mailOutInterner), gl::StrSpan(f.source),
        gl::StrSpan(child), key));
    const int32_t id = ((f.memory).mailOut).origins_.lookup(key);
    ASSERT_TRUE(id != 0);
    int zoomIns = 0;
    for (const gl::IntMailOrigin& origin : ((f.memory).mailOut).origins_.recordsAt(id))
        if (origin.tag == static_cast<uint8_t>(gl::OriginTag::zoomIn) && origin.deps.size() == 1) ++zoomIns;
    ASSERT_EQ(zoomIns, 1);
}

TEST(prover, admission_value_only_rewrite_preserves_excluded_anchor_rows) {
    SourceReplayFixture f;
    auto& m=f.memory;
    const int64_t key=gl::mintTemplateKey(((m).templateInterner),((m).nameMap),"(in3[c,marker,d])","main");
    gl::AdmissionMapValue fixed,changed;
    fixed.key={((m).valueInterner).encode("(Anchor[b])"),((m).valueInterner).encode("(in[b])")};
    fixed.remainingArgs={((m).valueInterner).encode("b")};
    fixed.ordisOnly=true;
    changed.key={((m).valueInterner).encode("(in[b])")};
    gl::insertAdmissionValue(((((m).overallHashMemory)).admissionMap),key,fixed,((m).valueInterner),f.arena);
    gl::insertAdmissionValue(((((m).overallHashMemory)).admissionMap),key,changed,((m).valueInterner),f.arena);
    gl::EquivalenceClass cls; cls.setMembersFromNames({"a","b"},((m).nameMap));
    f.analyzer.equivalenceAdmissionRewriter.applyEquivalenceClassToAdmissionMap(cls,m,gl::StrSpan("main"));
    const auto values=gl::admissionRecordsAt(((((m).overallHashMemory)).admissionMap),key,((m).valueInterner));
    ASSERT_EQ(values.size(),size_t(2));
    bool anchor=false,canonical=false;
    for(const auto& row:values) {
        if(row.ordisOnly) {
            ASSERT_TRUE(row.key==fixed.key && row.remainingArgs==fixed.remainingArgs);
            anchor=true;
        } else {
            ASSERT_EQ(((m).valueInterner).decode(row.key[0]),std::string("(in[a])"));
            canonical=true;
        }
    }
    ASSERT_TRUE(anchor && canonical);
    const auto epoch=((((m).overallHashMemory)).admissionMap).inner().insertEpoch();
    f.analyzer.equivalenceAdmissionRewriter.applyEquivalenceClassToAdmissionMap(cls,m,gl::StrSpan("main"));
    ASSERT_EQ(((((m).overallHashMemory)).admissionMap).inner().insertEpoch(),epoch);
}

TEST(memory, canonical_source_index_replaces_only_the_selected_owner) {
    SourceReplayFixture f;
    auto& index=((f.memory).lbMemory).existenceLookups.algebraSources;
    index.add(11,101); index.add(12,101); index.add(11,102); index.add(13,103);
    index.add(11,101);
    index.eraseOwner(101,f.arena);
    std::set<int64_t> found;
    index.postings.forEach(11,[&](int64_t key){found.insert(key);});
    ASSERT_TRUE(found==std::set<int64_t>({102}));
    found.clear(); index.owners.forEach(101,[&](int64_t key){found.insert(key);});
    ASSERT_TRUE(found.empty());
    index.add(14,101); index.remove(14,101); index.remove(14,101);
    found.clear(); index.postings.forEach(13,[&](int64_t key){found.insert(key);});
    ASSERT_TRUE(found==std::set<int64_t>({103}));
    ASSERT_TRUE(index.liveBytes()>0);
    index.clear();
    ASSERT_FALSE(index.built);
    ASSERT_EQ(index.liveBytes(),0);
}

TEST(prover, counterexample_preparation_is_disintegration_only_and_one_witness) {
    SourceReplayFixture f;
    gl::CompiledDefinitionFixture::compiledExpressions(f.analyzer.definitions)["implication96"] = gl::LogicalEntity("implication",
        {"(in[w,u_1])", "(in3[u_2,u_3,w,u_4])", "(=[w,u_2])"},
        "(implication96[u_1,u_2,u_3,u_4])", 4);
    const std::string source = "!(implication96[u_1,u_2,u_2,u_4])";
    gl::WorkInstruction integration(&f.arena), construction(&f.arena);
    const int pi = ((f.memory).startIntPi);
    f.analyzer.integrationBuilder.prepareIntegrationCore(gl::StrSpan(source), integration, f.memory, gl::StrSpan(source));
    ASSERT_EQ(integration.entityCount(), 0);
    ASSERT_EQ(((f.memory).startIntPi), pi);
    f.analyzer.integrationBuilder.prepareIntegrationCore(gl::StrSpan(source), construction, f.memory, gl::StrSpan(source), true);
    ASSERT_TRUE(gl::equalSpans(construction.category(0), gl::StrSpan("counterexample",14)));
    ASSERT_TRUE(gl::equalSpans(construction.signature(0), gl::StrSpan(source)));
    ASSERT_EQ(construction.elemCount(0), 3);
    ASSERT_TRUE(gl::startsWithSpan(construction.elemAt(0,2), "!(=[", 4));
    ASSERT_EQ(((f.memory).startIntPi), pi + 1);
    const int entities = construction.entityCount();
    f.analyzer.integrationBuilder.prepareIntegrationCore(gl::StrSpan(source), construction, f.memory, gl::StrSpan(source), true);
    ASSERT_EQ(construction.entityCount(), entities);
    ASSERT_EQ(((f.memory).startIntPi), pi + 1);
    for (const auto& elements : std::vector<std::vector<std::string>>{
            {"(in[u_1,u_2])", "(=[u_1,u_2])"},
            {"(in[w,u_1])", "(in[z,u_1])", "(=[w,z])"}}) {
        gl::CompiledDefinitionFixture::compiledExpressions(f.analyzer.definitions)["implication97"] = gl::LogicalEntity("implication",
            elements, "(implication97[u_1,u_2])", 2);
        gl::WorkInstruction unchanged(&f.arena);
        const std::string other = "!(implication97[u_1,u_2])";
        f.analyzer.integrationBuilder.prepareIntegrationCore(gl::StrSpan(other), unchanged, f.memory, gl::StrSpan(other), true);
        ASSERT_EQ(unchanged.entityCount(), 0);
        ASSERT_EQ(((f.memory).startIntPi), pi + 1);
    }
}

TEST(prover, counterexample_admits_one_integration_witness_without_demand_and_replays_once) {
    SourceReplayFixture f;
    f.source = "!(implication96[1,2,3,4])";
    gl::CompiledDefinitionFixture::compiledExpressions(f.analyzer.definitions)["implication96"] = gl::LogicalEntity("implication",
        {"(in[w,u_1])", "(in3[u_2,u_3,w,u_4])", "(=[w,u_2])"},
        "(implication96[u_1,u_2,u_3,u_4])", 4);
    const std::string scope = f.child();
    const int start = ((f.memory).startInt);
    f.analyzer.parameters.ban_disintegration = true;
    gl::DisintProducts rejected(&f.arena);
    f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
        gl::StrSpan(scope), rejected, true, false, f.levels, 2, false);
    ASSERT_EQ(((f.memory).startInt), start);
    ASSERT_TRUE(((f.memory).exprOriginMap).empty());
    ASSERT_TRUE(((f.memory).mailOut).origins_.empty());
    f.analyzer.parameters.ban_disintegration = false;
    gl::DisintProducts admitted(&f.arena);
    f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
        gl::StrSpan(scope), admitted, true, false, f.levels, 2, false);
    ASSERT_EQ(((f.memory).startInt), start + 1);
    const std::string witness = "int_0_lev_2_" + std::to_string(start);
    std::set<std::string> facts;
    admitted.statements.forEachSorted([&](gl::StrSpan text, gl::StrSpan validity) {
        ASSERT_TRUE(gl::equalSpans(validity, gl::StrSpan(scope)));
        facts.insert(std::string(text.ptr, text.len));
    });
    ASSERT_TRUE(facts.count("(in[" + witness + ",1])") == 1);
    ASSERT_TRUE(facts.count("(in3[2,3," + witness + ",4])") == 1);
    ASSERT_TRUE(facts.count("!(=[" + witness + ",2])") == 1);
    const std::string expanded = "!(>[" + witness + "](in[" + witness
        + ",1])(>[](in3[2,3," + witness + ",4])(=[" + witness + ",2])))";
    const auto history = gl::decodeOriginMapSorted(((f.memory).exprOriginMap), ((f.memory).originInterner));
    const auto hasHistory = [&](const std::string& fact, const std::string& tag, const std::string& source) {
        for (const auto& row : history) {
            if (row.first != std::make_pair(fact, scope)) continue;
            for (const auto& origin : row.second)
                if (origin.first == tag && origin.second.size() == 1
                    && origin.second[0].original == source && origin.second[0].validityName == scope)
                    return true;
        }
        return false;
    };
    ASSERT_TRUE(hasHistory(expanded, "expansion", f.source));
    for (const std::string& fact : facts) {
        if (fact == f.source) continue;
        ASSERT_TRUE(hasHistory(fact, "disintegration", expanded));
    }
    gl::DisintProducts replay(&f.arena);
    f.analyzer.disintegrationProcessor.disintegrateExpr2(gl::StrSpan(f.source), f.memory, 0, false,
        gl::StrSpan(scope), replay, true, false, f.levels, 2, false);
    ASSERT_EQ(((f.memory).startInt), start + 1);
}

