// Gate 1 at the deposit door: an ordinary value admits the witness of a
// hidden-argument original, yet the product moves no induction chain; a
// numbers-only original moves it to its next demand, filed in the induction
// scope the eat opened (D-519).
TEST(prover, product_of_a_hidden_argument_original_moves_no_induction_chain) {
    for (const bool hidden : {true, false}) {
        SourceReplayFixture f;
        if (hidden) f.source = "(existence96[force_lev_1_5,2,3,4])";
        f.demand("main");
        f.inductionDemand("main", {"(in3[2,3,9,4])", "(in3[9,5,10,4])"}, {"2", "3", "4", "5"});
        const int initial = ((f.memory).startInt);
        f.deposit();
        ASSERT_EQ(((f.memory).startInt), initial + 1);
        const std::string witness = "it_0_lev_2_" + std::to_string(initial);
        const std::string next = "(in3[" + witness + ",5,marker,4])";
        ASSERT_FALSE(f.demandFiled(next));
        const std::vector<std::string> scopes = f.inductionScopes();
        ASSERT_EQ(scopes.empty(), hidden);
        if (!hidden) {
            ASSERT_EQ(scopes.size(), static_cast<std::size_t>(1));
            ASSERT_TRUE(f.demandFiled(next, scopes[0]));
        }
    }
}

// An eat of the hypothesis opens one induction scope named by the chain with
// the eaten variable as the marker and the admitted witness; the witness's
// facts live there, the source stays at main, and the source's zoom into the
// scope is recorded (D-519).
TEST(prover, induction_admission_opens_an_induction_scope) {
    SourceReplayFixture f;
    f.inductionDemand("main", {"(in3[2,3,9,4])", "(in3[9,5,10,4])"}, {"2", "3", "4", "5"});
    const int initial = ((f.memory).startInt);
    f.deposit();
    const std::string witness = "it_0_lev_2_" + std::to_string(initial);
    const std::vector<std::string> scopes = f.inductionScopes();
    ASSERT_EQ(scopes.size(), static_cast<std::size_t>(1));
    const std::string prefix = "main_boundary_is_(in3[2,3,marker,4])(in3[marker,5,";
    ASSERT_TRUE(scopes[0].compare(0, prefix.size(), prefix) == 0);
    const std::string suffix = ",4])_" + witness;
    ASSERT_TRUE(scopes[0].size() > suffix.size()
        && scopes[0].compare(scopes[0].size() - suffix.size(), suffix.size(), suffix) == 0);
    ASSERT_TRUE(f.known("(in3[2,3," + witness + ",4])", scopes[0]));
    ASSERT_TRUE(f.known("(in[" + witness + ",1])", scopes[0]));
    ASSERT_FALSE(f.known("(in[" + witness + ",1])", "main"));
    ASSERT_TRUE(f.known(f.source, "main"));
    int64_t zoomKey = 0;
    ASSERT_TRUE(gl::lookupOriginKey(((f.memory).originInterner), f.source, scopes[0], zoomKey));
    const int32_t zoomId = ((f.memory).exprOriginMap).lookup(zoomKey);
    ASSERT_TRUE(zoomId != 0);
    bool zoomed = false;
    for (const gl::IdOrigin& origin : ((f.memory).exprOriginMap).recordsAt(zoomId))
        zoomed |= origin.first == gl::OriginTag::zoomIn;
    ASSERT_TRUE(zoomed);
}

// An in-place feed of the hypothesis's chain advances the chain at main and is
// an eat: the existing name that fills the eaten element opens the induction
// scope named by that name, a copy of the advanced chain's demand is filed
// there, and the eat is recorded at main; in a settled tree the chain only
// advances in place (D-546).
TEST(prover, in_place_feed_of_the_hypothesis_opens_an_induction_scope) {
    for (const bool settled : {false, true}) {
        SourceReplayFixture f;
        f.inductionDemand("main", {"(in3[2,3,9,4])", "(in3[9,5,10,4])"}, {"2", "3", "4", "5"});
        if (settled) ((f.memory).lbMemory).inductionSettledRoots.mint(gl::NameMap::MAIN_ID);
        f.depositAt("(in3[2,3,7,4])", "main");
        const std::vector<std::string> scopes = f.inductionScopes();
        if (settled) {
            ASSERT_TRUE(scopes.empty());
            ASSERT_TRUE(f.demandFiled("(in3[7,5,marker,4])", "main"));
            continue;
        }
        ASSERT_EQ(scopes.size(), static_cast<std::size_t>(1));
        const std::string prefix = "main_boundary_is_(in3[2,3,marker,4])(in3[marker,5,";
        ASSERT_TRUE(scopes[0].compare(0, prefix.size(), prefix) == 0);
        const std::string suffix = ",4])_7";
        ASSERT_TRUE(scopes[0].size() > suffix.size()
            && scopes[0].compare(scopes[0].size() - suffix.size(), suffix.size(), suffix) == 0);
        ASSERT_TRUE(f.demandFiled("(in3[7,5,marker,4])", scopes[0]));
        ASSERT_TRUE(f.demandFiled("(in3[7,5,marker,4])", "main"));
        ASSERT_TRUE((f.memory).inductionEatenSlot(gl::NameMap::MAIN_ID) != nullptr);
    }
}

// One order per path for in-place eats: once the hypothesis ate one slot at
// main in place, an in-place feed of its other slot still advances the chain
// at main but opens no second scope (D-546).
TEST(prover, in_place_feed_of_another_slot_advances_without_a_scope) {
    SourceReplayFixture f;
    const std::vector<std::string> chain = {"(in3[2,3,9,4])", "(in3[5,6,10,4])"};
    const std::vector<std::string> remaining = {"2", "3", "4", "5", "6"};
    f.inductionDemandAt("(in3[2,3,marker,4])", "main", chain, remaining);
    f.inductionDemandAt("(in3[5,6,marker,4])", "main", chain, remaining);
    f.depositAt("(in3[2,3,7,4])", "main");
    ASSERT_EQ(f.inductionScopes().size(), static_cast<std::size_t>(1));
    f.depositAt("(in3[5,6,8,4])", "main");
    ASSERT_EQ(f.inductionScopes().size(), static_cast<std::size_t>(1));
    const gl::NameId text = ((f.memory).templateInterner).lookup(gl::StrSpan(std::string("(in3[2,3,marker,4])")));
    const int32_t run = ((((f.memory).overallHashMemory)).admissionMap).lookup(
        gl::packInt32Pair(text, gl::NameMap::MAIN_ID));
    ASSERT_TRUE(run != 0);
    ASSERT_EQ(((((f.memory).overallHashMemory)).admissionMap).runLen(run), 2);
}

// No backward readmission (D-519): inside the scope an
// eat opened, the same chain admits no second witness, probe and replay
// alike; a forward chain filed in the scope still admits there, and the same
// chain still admits at a sibling of the scope.
TEST(prover, induction_scope_refuses_a_backward_readmission) {
    SourceReplayFixture f;
    f.inductionDemand("main", {"(in3[2,3,9,4])"}, {"2", "3", "4"});
    f.deposit();
    const std::vector<std::string> scopes = f.inductionScopes();
    ASSERT_EQ(scopes.size(), static_cast<std::size_t>(1));
    const std::string candidate = "(in3[2,3,w,4])";
    const gl::StrSpan witness("w", 1);
    const auto probe = [&](const std::string& scope) {
        return f.analyzer.admissionMemory.isAdmittedIncludingAncestors(f.memory, gl::StrSpan(candidate),
            witness, gl::StrSpan(f.marker), gl::StrSpan(scope), nullptr, false, true);
    };
    ASSERT_FALSE(probe(scopes[0]));
    ASSERT_TRUE(probe("main"));
    ASSERT_TRUE(probe(f.child("sibling")));
    f.park(false, "main");
    const int32_t before = ((f.memory).sameIterationInternalMail).statements_.count();
    f.wake(scopes[0]);
    ASSERT_EQ(((f.memory).sameIterationInternalMail).statements_.count(), before);
}

// Only the induction hypothesis opens induction scopes: a recursion-owned
// value without the hypothesis bit — the goal door's demand — admits its
// witness at the source's own scope and records no eat
// (D-519).
TEST(prover, goal_door_demand_opens_no_induction_scope) {
    SourceReplayFixture f;
    f.inductionDemand("main", {"(in3[2,3,9,4])"}, {"2", "3", "4"}, false);
    const int initial = ((f.memory).startInt);
    f.deposit();
    ASSERT_EQ(((f.memory).startInt), initial + 1);
    const std::string witness = "it_0_lev_2_" + std::to_string(initial);
    ASSERT_TRUE(f.inductionScopes().empty());
    ASSERT_TRUE(f.known("(in3[2,3," + witness + ",4])", "main"));
    ASSERT_TRUE(f.memory.inductionEatenSlot(gl::NameMap::MAIN_ID) == nullptr);
}

// The statement door records a firing of the induction hypothesis's head at an
// induction scope; the same head at a root, or any other deposit at the scope,
// records none (D-520).
TEST(prover, hypothesis_head_at_an_induction_scope_records_a_firing) {
    gl::tests::ProverFixture analyzer("Peano");
    gl::Memory& memory = analyzer.body;
    memory.isActive = true;
    const gl::NameId leafId = memory.nameMap.encodePush(gl::NameMap::MAIN_ID,
        std::string("is_(in3[2,3,marker,4])_it_0_lev_2_7"));
    const std::string leaf = memory.nameMap.decode(leafId);
    const int lv[1] = { 2 };
    const gl::TransientOrigin origin{ true, gl::OriginTag::broadcast, nullptr, 0 };
    analyzer.statementMemory.addExprToMemoryBlock(gl::StrSpan("(in[a,1])", 9), memory, 0, 1,
        lv, 1, origin, -1, -1, gl::StrSpan(leaf), false, false, nullptr, false);
    ASSERT_TRUE(memory.lbMemory.inductionFirings.empty());
    analyzer.statementMemory.addExprToMemoryBlock(gl::StrSpan("(in[b,1])", 9), memory, 0, 1,
        lv, 1, origin, -1, -1, gl::StrSpan("main", 4), false, false, nullptr, true);
    ASSERT_TRUE(memory.lbMemory.inductionFirings.empty());
    analyzer.statementMemory.addExprToMemoryBlock(gl::StrSpan("(in[c,1])", 9), memory, 0, 1,
        lv, 1, origin, -1, -1, gl::StrSpan(leaf), false, false, nullptr, true);
    ASSERT_EQ(memory.lbMemory.inductionFirings.count(), 1);
    ASSERT_EQ(memory.lbMemory.inductionFirings.decode(1), leafId);
}

// A settled induction tree admits nothing more through the hypothesis
// (D-520): the demand that opens a scope in an open tree
