namespace {
    /// Span run over caller-stable std::string storage for the ordis tests
    /// (a StrSpan over a literal would dangle — 09c pitfall 1).
    struct SpanRun {
        std::vector<std::string> storage;
        std::vector<gl::StrSpan> spans;
        explicit SpanRun(std::vector<std::string> s) : storage(std::move(s)) {
            for (const std::string& e : storage) spans.push_back(gl::StrSpan(e));
        }
        const gl::StrSpan* data() const { return spans.data(); }
        int32_t count() const { return static_cast<int32_t>(spans.size()); }
    };

    /// Count encodedMap LMV records, split by the ordisOnly tag.
    void countLmvRecords(gl::TypedColdBlobMap<gl::NormKey, gl::LocalMemoryValue>& em,
                         int32_t& tagged, int32_t& untagged) {
        tagged = 0;
        untagged = 0;
        for (int32_t id = 1; id <= em.count(); ++id) {
            for (int32_t j = 0; j < em.runLen(id); ++j) {
                const gl::LocalMemoryValue v = em.recordAt(id, j);
                if (v.ordisOnly) ++tagged; else ++untagged;
            }
        }
    }

    /// True when an installed derivative LMV retains an anchor premise.
    bool lmvKeyContainsAnchor(const gl::LocalMemoryValue& lmv,
                              const gl::ValueInterner& interner) {
        for (const int32_t id : lmv.keyIds) {
            const std::string elem = interner.decode(id);
            if (elem.rfind("(Anchor", 0) == 0) return true;
        }
        return false;
    }
} // namespace

// Admission keys normalize equality classes rather than pinning source names.
// A lone premise therefore cannot distinguish which anchor slot supplied an
// argument. Retaining the anchor restores that distinction while preserving
// ordinary alpha-renaming of the complete anchored key.
TEST(prover, admission_normalization_retained_anchor_preserves_bindings) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    const auto normalized = [&](const std::vector<std::string>& expressions) {
        std::vector<gl::IntEncodedExpr> encoded;
        encoded.reserve(expressions.size());
        for (const std::string& expression : expressions) {
            encoded.push_back(gl::encodeExpression(
                gl::StrSpan(expression), gl::StrSpan("main", 4), ((m).nameMap)));
        }
        gl::NameId buffer[gl::ExecutionParameters::MAX_KEY_SLOTS];
        const gl::NameId length = gl::HashKeyBuilder::makeIntNormalizedKeyFromEncoded(
            encoded.data(), static_cast<gl::NameId>(encoded.size()), false,
            buffer, gl::ExecutionParameters::MAX_KEY_SLOTS);
        return gl::NormKey{ static_cast<int32_t>(encoded.size()),
                            std::vector<gl::NameId>(buffer, buffer + length) };
    };

    const gl::NormKey loneSlot6 = normalized({ "(preorder[1,4,6,9])" });
    const gl::NormKey loneSlot2 = normalized({ "(preorder[1,4,2,9])" });
    ASSERT_TRUE(loneSlot6 == loneSlot2);

    const gl::NormKey anchoredSlot6 = normalized({
        "(AnchorFTA[1,2,3,4,5,6,7,8])", "(preorder[1,4,6,9])" });
    const gl::NormKey anchoredSlot2 = normalized({
        "(AnchorFTA[1,2,3,4,5,6,7,8])", "(preorder[1,4,2,9])" });
    ASSERT_FALSE(anchoredSlot6 == anchoredSlot2);

    const gl::NormKey renamedSlot6 = normalized({
        "(AnchorFTA[11,12,13,14,15,16,17,18])",
        "(preorder[11,14,16,19])" });
    ASSERT_TRUE(anchoredSlot6 == renamedSlot6);
}

// ordisRouteQualifies — the shape gate of the ordis-only admission route:
// every non-anchor element + the head must be operator applications; the
// count (head included, anchors excluded) must reach
// kOrdisMinOperatorExpressions (4). Row 34 (3 premises + head) passes at
// the boundary; equalities, typing atoms, and negations disqualify.
TEST(prover, ordis_route_qualifies_predicate) {
    gl::tests::ProverFixture ea("Peano");

    const std::string head = "(in3[10,11,9,4])";

    // Row-34 shape: 3 operator premises + operator head = 4 -> qualifies.
    SpanRun row34({ "(in3[7,8,9,4])", "(in2[8,10,3])", "(in2[11,7,3])" });
    ASSERT_TRUE(ea.admissionPolicy.ordisRouteQualifies(row34.data(), row34.count(),
                                       gl::StrSpan(head)));

    // Boundary fail: 2 premises + head = 3 < 4.
    SpanRun threeOps({ "(in3[7,8,9,4])", "(in2[8,10,3])" });
    ASSERT_TRUE(!ea.admissionPolicy.ordisRouteQualifies(threeOps.data(), threeOps.count(),
                                        gl::StrSpan(head)));

    // An anchor element is excluded from requirement AND count: anchor + 3
    // premises + head still = 4 (passes); anchor + 2 premises + head = 3.
    SpanRun withAnchor({ "(AnchorPeano[1,2,3,4,5,6])", "(in3[7,8,9,4])",
                         "(in2[8,10,3])", "(in2[11,7,3])" });
    ASSERT_TRUE(ea.admissionPolicy.ordisRouteQualifies(withAnchor.data(), withAnchor.count(),
                                       gl::StrSpan(head)));
    SpanRun anchorShort({ "(AnchorPeano[1,2,3,4,5,6])", "(in3[7,8,9,4])",
                          "(in2[8,10,3])" });
    ASSERT_TRUE(!ea.admissionPolicy.ordisRouteQualifies(anchorShort.data(), anchorShort.count(),
                                        gl::StrSpan(head)));

    // Non-operator elements disqualify: equality, typing atom, negation.
    SpanRun withEquality({ "(in3[7,8,9,4])", "(in2[8,10,3])", "(=[11,7])" });
    ASSERT_TRUE(!ea.admissionPolicy.ordisRouteQualifies(withEquality.data(),
                                        withEquality.count(), gl::StrSpan(head)));
    SpanRun withTyping({ "(in3[7,8,9,4])", "(in2[8,10,3])", "(in[11,1])" });
    ASSERT_TRUE(!ea.admissionPolicy.ordisRouteQualifies(withTyping.data(), withTyping.count(),
                                        gl::StrSpan(head)));
    SpanRun withNegation({ "(in3[7,8,9,4])", "(in2[8,10,3])", "!(in2[11,7,3])" });
    ASSERT_TRUE(!ea.admissionPolicy.ordisRouteQualifies(withNegation.data(),
                                        withNegation.count(), gl::StrSpan(head)));

    // Equality HEAD disqualifies.
    const std::string eqHead = "(=[10,11])";
    ASSERT_TRUE(!ea.admissionPolicy.ordisRouteQualifies(row34.data(), row34.count(),
                                        gl::StrSpan(eqHead)));
}

// The ordis candidate loop end-to-end through makeNormalizedKeysForAdmission:
// the row-34 shape (fails every regular gate) installs ordisOnly-tagged
// marker LMVs for candidate 11 — at a config input slot of its premise,
// present at a head input slot, confined, concrete. The per-candidate
// negatives (head-slot miss, confinement, concreteness) install nothing.
TEST(prover, ordis_route_installs_tagged_marker) {
    const std::string vld = "main";
    const std::string origImpl = "(row34-original)";
    const auto install = [&](const std::vector<std::string>& key,
                             const std::string& head, bool expectAnchor,
                             int32_t& tagged, int32_t& untagged) {
        gl::tests::ProverFixture ea("Peano");
        gl::Memory m;
        SpanRun run(key);
        ea.admissionMarkers.makeNormalizedKeysForAdmission(run.data(), run.count(),
            ((m).overallHashMemory), ((m).nameMap), ((m).ruleInterner),
            gl::StrSpan(head), 2, gl::StrSpan(origImpl), gl::StrSpan(vld));
        countLmvRecords(((((m).overallHashMemory)).encodedMap), tagged, untagged);
        for (int32_t id = 1; id <= ((((m).overallHashMemory)).encodedMap).count(); ++id) {
            for (int32_t j = 0;
                 j < ((((m).overallHashMemory)).encodedMap).runLen(id); ++j) {
                const gl::LocalMemoryValue lmv =
                    ((((m).overallHashMemory)).encodedMap).recordAt(id, j);
                if (!lmv.ordisOnly) continue;
                ASSERT_EQ(lmvKeyContainsAnchor(lmv, ((m).ruleInterner)), expectAnchor);
            }
        }
    };

    int32_t tagged = 0, untagged = 0;

    // Positive: candidate 11 in (in2[11,7,3]) — marker LMVs land tagged;
    // the regular route contributes nothing (all regular gates fail).
    install({ "(in3[7,8,9,4])", "(in2[8,10,3])", "(in2[11,7,3])" },
            "(in3[10,11,9,4])", false, tagged, untagged);
    ASSERT_TRUE(tagged > 0);
    ASSERT_EQ(untagged, 0);

    // The same non-anchor shape and eligibility count with an anchor retains
    // that anchor in every installed ordis-only derivative key.
    install({ "(AnchorPeano[1,2,3,4,5,6])", "(in3[7,8,9,4])",
              "(in2[8,10,3])", "(in2[11,7,3])" },
            "(in3[10,11,9,4])", true, tagged, untagged);
    ASSERT_TRUE(tagged > 0);
    ASSERT_EQ(untagged, 0);

    // Head-slot negative: 11 not at a head input slot (head inputs {10,7};
    // the 7 candidate then fails confinement against (in2[11,7,3])).
    install({ "(in3[7,8,9,4])", "(in2[8,10,3])", "(in2[11,7,3])" },
            "(in3[10,7,9,4])", false, tagged, untagged);
    ASSERT_EQ(tagged, 0);
    ASSERT_EQ(untagged, 0);

    // Confinement negative: 11 also appears in the first premise.
    install({ "(in3[11,8,9,4])", "(in2[8,10,3])", "(in2[11,7,3])" },
            "(in3[10,11,9,4])", false, tagged, untagged);
    ASSERT_EQ(tagged, 0);
    ASSERT_EQ(untagged, 0);

    // Concreteness negative: the marked premise's other arg 3 is bound
    // nowhere in the subkey (premise 2 now carries 5 instead of 3).
    install({ "(in3[7,8,9,4])", "(in2[8,10,5])", "(in2[11,7,3])" },
            "(in3[10,11,9,4])", false, tagged, untagged);
    ASSERT_EQ(tagged, 0);
    ASSERT_EQ(untagged, 0);

    // Shape negative: dropping a premise (3 operator expressions) installs
    // nothing at all.
    install({ "(in3[7,8,9,4])", "(in2[11,7,3])" },
            "(in3[10,11,9,4])", false, tagged, untagged);
    ASSERT_EQ(tagged, 0);
    ASSERT_EQ(untagged, 0);
}

// The arithmetic-qualified regular route never selects the anchor as the
// missing premise and keeps it even when it contains the selected output.
TEST(prover, regular_admission_route_retains_anchor_context) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    SpanRun run({ "(AnchorPeano[1,2,3,4,5,6])", "(in2[7,2,3])",
                  "(in3[9,10,11,4])", "(in2[11,12,3])",
                  "(in3[13,14,15,4])", "(in3[16,17,18,4])" });
    ea.admissionMarkers.makeNormalizedKeysForAdmission(run.data(), run.count(),
        ((m).overallHashMemory), ((m).nameMap), ((m).ruleInterner),
        gl::StrSpan("(in3[13,16,19,4])"), 2, gl::StrSpan("(regular-original)"),
        gl::StrSpan("main"));

    int regularCount = 0;
    bool foundAnchorBoundOutput = false;
    for (int32_t id = 1; id <= ((((m).overallHashMemory)).encodedMap).count(); ++id) {
        for (int32_t j = 0; j < ((((m).overallHashMemory)).encodedMap).runLen(id); ++j) {
            const gl::LocalMemoryValue lmv =
                ((((m).overallHashMemory)).encodedMap).recordAt(id, j);
            if (lmv.ordisOnly || lmv.ordis2Demand) continue;
            ++regularCount;
            ASSERT_TRUE(lmvKeyContainsAnchor(lmv, ((m).ruleInterner)));
            const std::string value = ((m).ruleInterner).decode(lmv.valueId);
            ASSERT_FALSE(value.rfind("(Anchor", 0) == 0);
            if (value == "(in2[7,marker,3])") {
                foundAnchorBoundOutput = true;
                ASSERT_EQ(lmv.keyIds.size(), static_cast<std::size_t>(5));
            }
        }
    }
    ASSERT_TRUE(regularCount > 0);
    ASSERT_TRUE(foundAnchorBoundOutput);
}

namespace {

    /// Mint `main -> childscope` and return the child's canonical name.
    std::string mintChildScope(gl::Memory& m, gl::NameId& childIdOut) {
        const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
        childIdOut = ((m).nameMap).encodePush(mainId, std::string("childscope"));
        return ((m).nameMap).decode(childIdOut);
    }

} // namespace

// applyEquivalenceClassToRejectedMap — drops the changed key and mails the
// rewritten compound onto sameIterationInternalMail (drop + mail, never a
// direct re-key into rejectedMap).
// Re-key in place (D-308): a park whose key names a
// non-canonical class member and whose rewritten product is not demanded is
// re-inserted under the canonical key with every text rewritten, its levels
// kept, and one complete `equality1` history row for the rewritten product
// at the park scope; nothing is mailed.
TEST(prover, apply_equi_rejected_rekeys_in_place_when_undemanded) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    auto& rm = ((((m).overallHashMemory)).rejectedMap);

    const int64_t oldPk = gl::mintTemplateKey(((m).templateInterner), ((m).nameMap),
        "(in2[it_5_lev_1_2,marker,3])", "main");
    gl::RejectedMapValue rv;
    rv.sourceExpression = ((m).valueInterner).encode("(existence0[1,it_5_lev_1_2,3])");
    rv.flags = 1;



    rv.levels = std::set<int>{ 0 };
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);
    gl::insertRejectedValue(rm, oldPk, rv, ((m).valueInterner), tArena);

    gl::EquivalenceClass cls;
    cls.setMembersFromNames({ "it_0_lev_1_2", "it_5_lev_1_2" }, ((m).nameMap));

    gl::DirtyState bucketDirty = gl::DirtyState::Clean;
    gl::RejectedValidityBuckets buckets(&tArena, &bucketDirty);
    const int32_t hits =
        ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMap(cls, m, gl::StrSpan("main", 4), buckets);
    ASSERT_EQ(hits, 1);

    // Old key gone, canonical key present with the rewritten record.
    ASSERT_TRUE(rm.lookup(oldPk) == 0);
    int64_t newPk = 0;
    ASSERT_TRUE(gl::lookupTemplateKey(((m).templateInterner), ((m).nameMap),
        gl::StrSpan(std::string("(in2[it_0_lev_1_2,marker,3])")), gl::StrSpan("main", 4), newPk));
    ASSERT_TRUE(rm.lookup(newPk) != 0);
    ASSERT_EQ(rm.count(), 1);
    const gl::RejectedValueSet recs = gl::rejectedRecordsAt(rm, newPk, ((m).valueInterner));
    ASSERT_EQ(recs.size(), static_cast<std::size_t>(1));
    const gl::RejectedMapValue& v = *recs.begin();
    ASSERT_TRUE(((m).valueInterner).decode(v.sourceExpression) == "(existence0[1,it_0_lev_1_2,3])");




    ASSERT_TRUE(v.levels == (std::set<int>{ 0 }));
    ASSERT_TRUE(((m).mutatedThisBurst));

    // Nothing mailed.
    ASSERT_EQ(gl::decodeInternalMailStatements(((m).sameIterationInternalMail),
        ((m).nameMap)).size(), static_cast<std::size_t>(0));

    ASSERT_TRUE(((m).exprOriginMap).empty());
    ASSERT_EQ(v.rewrites.size(), size_t(3));
    ASSERT_EQ(((m).valueInterner).decode(v.rewrites[0]), std::string("(existence0[1,it_5_lev_1_2,3])"));
    ASSERT_EQ(((m).valueInterner).decode(v.rewrites[1]), std::string("(existence0[1,it_0_lev_1_2,3])"));
    ASSERT_EQ(((m).valueInterner).decode(v.rewrites[2]), std::string("(=[it_5_lev_1_2,it_0_lev_1_2])"));
}

// Site-F parity: a park whose rewritten compound is already local at the
// scope (or known at a strict ancestor) is dropped, not re-keyed — exactly
// what the absorb did to the re-sent compound.
TEST(prover, apply_equi_rejected_keeps_known_source_eligible_for_witness_replay) {
    gl::tests::ProverFixture ea("Peano");
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);
    auto park = [&](gl::Memory& m, const char* scope) {
        const int64_t pk = gl::mintTemplateKey(((m).templateInterner), ((m).nameMap),
            "(in2[it_5_lev_1_2,marker,3])", scope);
        gl::RejectedMapValue rv;
        rv.sourceExpression = ((m).valueInterner).encode("(existence0[1,it_5_lev_1_2,3])");
    rv.flags = 1;


        rv.levels = std::set<int>{ 0 };
        gl::insertRejectedValue(((((m).overallHashMemory)).rejectedMap), pk, rv,
                                ((m).valueInterner), tArena);
        return pk;
    };
    auto classOf = [&](gl::Memory& m) {
        gl::EquivalenceClass cls;
        cls.setMembersFromNames({ "it_0_lev_1_2", "it_5_lev_1_2" }, ((m).nameMap));
        return cls;
    };

    // (a) rewritten compound LOCAL at the park scope -> dropped.
    {
        gl::Memory m;
        const int64_t pk = park(m, "main");
        const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
        const gl::NameId cId = ((m).nameMap).encode(std::string("(existence0[1,it_0_lev_1_2,3])"));
        gl::upsertStatementKey(((m).intKnownStatements),
            gl::packStatementKey(cId, mainId), /*local=*/true);
        ((m).intLocalEncodedStatementsSet).mint(gl::packStatementKey(cId, mainId));
        const gl::EquivalenceClass cls = classOf(m);
        gl::DirtyState d = gl::DirtyState::Clean;
        gl::RejectedValidityBuckets b(&tArena, &d);
        ASSERT_EQ(ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMap(cls, m, gl::StrSpan("main", 4), b), 1);
        ASSERT_TRUE(((((m).overallHashMemory)).rejectedMap).lookup(pk) == 0);
        ASSERT_EQ(((((m).overallHashMemory)).rejectedMap).count(), 1);
        ASSERT_EQ(gl::decodeInternalMailStatements(((m).sameIterationInternalMail),
            ((m).nameMap)).size(), static_cast<std::size_t>(0));
        ASSERT_EQ(gl::decodeOriginMapSorted(((m).exprOriginMap), ((m).originInterner)).size(),
                  static_cast<std::size_t>(0));
    }
    // (b) rewritten compound KNOWN at a strict ancestor of the park scope -> dropped.
    {
        gl::Memory m;
        gl::NameId childId = 0;
        const std::string childName = mintChildScope(m, childId);
        const int64_t pk = park(m, childName.c_str());
        const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
        const gl::NameId cId = ((m).nameMap).encode(std::string("(existence0[1,it_0_lev_1_2,3])"));
        gl::upsertStatementKey(((m).intKnownStatements),
            gl::packStatementKey(cId, mainId), /*local=*/false);
        const gl::EquivalenceClass cls = classOf(m);
        gl::DirtyState d = gl::DirtyState::Clean;
        gl::RejectedValidityBuckets b(&tArena, &d);
        ASSERT_EQ(ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMap(cls, m, gl::StrSpan(childName), b), 1);
        ASSERT_TRUE(((((m).overallHashMemory)).rejectedMap).lookup(pk) == 0);
        ASSERT_EQ(((((m).overallHashMemory)).rejectedMap).count(), 1);
    }
    // (c) rewritten compound known at the park scope but NOT local (mailed in)
    //     -> re-keyed (the absorb would have wiped and re-disintegrated it).
    {
        gl::Memory m;
        const int64_t pk = park(m, "main");
        const gl::NameId mainId = ((m).nameMap).encode(std::string("main"));
        const gl::NameId cId = ((m).nameMap).encode(std::string("(existence0[1,it_0_lev_1_2,3])"));
        gl::upsertStatementKey(((m).intKnownStatements),
            gl::packStatementKey(cId, mainId), /*local=*/false);
        const gl::EquivalenceClass cls = classOf(m);
        gl::DirtyState d = gl::DirtyState::Clean;
        gl::RejectedValidityBuckets b(&tArena, &d);
        ASSERT_EQ(ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMap(cls, m, gl::StrSpan("main", 4), b), 1);
        ASSERT_TRUE(((((m).overallHashMemory)).rejectedMap).lookup(pk) == 0);
        ASSERT_EQ(((((m).overallHashMemory)).rejectedMap).count(), 1);
    }
}

// D-280 under the re-key: the re-keyed record's level run is the parked run
// UNIONED with the fired pair's stored levels.
TEST(prover, apply_equi_rejected_rekey_unions_pair_levels) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    auto& rm = ((((m).overallHashMemory)).rejectedMap);

    const int64_t oldPk = gl::mintTemplateKey(((m).templateInterner), ((m).nameMap),
        "(in2[it_5_lev_1_2,marker,3])", "main");
    gl::RejectedMapValue rv;
    rv.sourceExpression = ((m).valueInterner).encode("(in3[it_5_lev_1_2,7,3,plus])");
    rv.flags = 1;


    rv.levels = std::set<int>{ 0 };
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);
    gl::insertRejectedValue(rm, oldPk, rv, ((m).valueInterner), tArena);

    gl::EquivalenceClass cls;
    cls.setMembersFromNames({ "it_0_lev_1_2", "it_5_lev_1_2" }, ((m).nameMap));
    cls.intEqualityLevelsMap[gl::packEqPairKey(
        ((m).nameMap).encode("it_0_lev_1_2"),
        ((m).nameMap).encode("it_5_lev_1_2"))] = std::set<int>{ 1, 3 };

    gl::DirtyState bucketDirty = gl::DirtyState::Clean;
    gl::RejectedValidityBuckets buckets(&tArena, &bucketDirty);
    ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMap(cls, m, gl::StrSpan("main", 4), buckets);

    int64_t newPk = 0;
    ASSERT_TRUE(gl::lookupTemplateKey(((m).templateInterner), ((m).nameMap),
        gl::StrSpan(std::string("(in2[it_0_lev_1_2,marker,3])")), gl::StrSpan("main", 4), newPk));
    const gl::RejectedValueSet recs = gl::rejectedRecordsAt(rm, newPk, ((m).valueInterner));
    ASSERT_EQ(recs.size(), static_cast<std::size_t>(1));
    ASSERT_TRUE(recs.begin()->levels == (std::set<int>{ 0, 1, 3 }));
}

// The fork: a rewritten product that is demanded right now (a regular
// admission entry under the canonical key at the park scope) takes the old
// path — the key is dropped and the rewritten compound is mailed with its
// equality1 history line, so the absorb's Pass B admits it; no park is
// written under the canonical key.
TEST(prover, apply_equi_rejected_demanded_compound_still_mails) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    auto& rm = ((((m).overallHashMemory)).rejectedMap);
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);

    const int64_t oldPk = gl::mintTemplateKey(((m).templateInterner), ((m).nameMap),
        "(in2[it_5_lev_1_2,marker,3])", "main");
    gl::RejectedMapValue rv;
    rv.sourceExpression = ((m).valueInterner).encode("(existence0[1,it_5_lev_1_2,3])");
    rv.flags = 1;


    rv.levels = std::set<int>{ 0 };
    gl::insertRejectedValue(rm, oldPk, rv, ((m).valueInterner), tArena);

    // The demand: a regular admission entry under the canonical key.
    const int64_t demandPk = gl::mintTemplateKey(((m).templateInterner), ((m).nameMap),
        "(in2[it_0_lev_1_2,marker,3])", "main");
    gl::AdmissionMapValue value;
    value.standardMaxAdmissionDepth = 30;
    value.standardMaxSecondaryNumber = 2;
    ((((m).overallHashMemory)).admissionStatusMap).upsert(demandPk, uint8_t(0));
    value.key = encodeValueVectorOracle(
        std::vector<std::string>{ "(in2[it_0_lev_1_2,7,3])" }, ((m).valueInterner));
    gl::insertAdmissionValue(((((m).overallHashMemory)).admissionMap), demandPk,
                             value, ((m).valueInterner), tArena);

    gl::EquivalenceClass cls;
    cls.setMembersFromNames({ "it_0_lev_1_2", "it_5_lev_1_2" }, ((m).nameMap));

    seedFixtureClassEvidence(m,cls,gl::StrSpan("main"));
    gl::DirtyState bucketDirty = gl::DirtyState::Clean;
    gl::RejectedValidityBuckets buckets(&tArena, &bucketDirty);
    const int32_t hits =
        ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMap(cls, m, gl::StrSpan("main", 4), buckets);
    ASSERT_EQ(hits, 1);

    ASSERT_TRUE(rm.lookup(oldPk) == 0);
    ASSERT_TRUE(rm.lookup(demandPk) != 0);
    ASSERT_EQ(rm.count(), 1);

    bool foundMail = false;
    const gl::Mail mailSnap = gl::makeHeapMail(((m).sameIterationInternalMail),
                                               ((m).nameMap), ((m).originInterner));
    for (const auto& pr : mailSnap.statements) {
        if (pr.first.original == "(existence0[1,it_0_lev_1_2,3])"
            && pr.first.validityName == "main") {
            foundMail = true;
            ASSERT_TRUE(pr.second == (std::set<int>{ 0 }));
        }
    }
    ASSERT_TRUE(foundMail);
    const auto history = gl::decodeOriginMapSorted(((m).exprOriginMap), ((m).originInterner));
    ASSERT_EQ(history.size(), size_t(3));
    ASSERT_EQ(history[2].first.first, std::string("(existence0[1,it_0_lev_1_2,3])"));
    ASSERT_EQ(history[2].second[0].first, std::string("equality1"));
    ASSERT_EQ(history[2].second[0].second[0].original, std::string("(existence0[1,it_5_lev_1_2,3])"));
    ASSERT_EQ(history[2].second[0].second[1].original, std::string("(=[it_5_lev_1_2,it_0_lev_1_2])"));
}
// Integration twin: the park is re-keyed under the bare canonical key with
// concrete / compound / siblings rewritten, the canonical key's arguments
// join varsInRejectedMapIntegrationKeys, the rewritten product gets its
// equality1 row, the unchanged sibling none; nothing is mailed.
TEST(prover, apply_equi_rejected_integration_rekeys_in_place) {
    gl::tests::ProverFixture ea("Peano");
    gl::Memory m;
    auto& rmi = ((((m).overallHashMemory)).rejectedMapIntegration);
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);

    const std::string marked   = "(in2[q,marker,3])";
    const std::string concrete = "(in2[q,int_0_lev_1_9,3])";
    const std::string compound = "(existence0[1,q,3])";
    const std::string sibling  = "(in[int_0_lev_1_9,1])";
    const int32_t sibIds[1] = { ((m).valueInterner).encode(gl::StrSpan(sibling)) };
    const int64_t oldPk = gl::mintTemplateKey(((m).templateInterner), ((m).nameMap),
                                              marked, std::string("main"));
    gl::insertRejectedIntegrationIdsBlob(
            rmi, oldPk, ((m).valueInterner).encode(gl::StrSpan(compound)), 0, 2, nullptr, 0, nullptr, 0, ((m).valueInterner), tArena);
    ((((m).overallHashMemory)).varsInRejectedMapIntegrationKeys).mint(
        ((m).templateInterner).encode("q"));

    gl::EquivalenceClass cls;
    cls.setMembersFromNames({ "p", "q" }, ((m).nameMap));   // canonical: p

    gl::DirtyState bucketDirty = gl::DirtyState::Clean;
    gl::RejectedValidityBuckets buckets(&tArena, &bucketDirty);
    const int32_t hits = ea.equivalenceAdmissionRewriter.applyEquivalenceClassToRejectedMapIntegration(
        cls, m, gl::StrSpan("main", 4), buckets);
    ASSERT_EQ(hits, 1);

    ASSERT_TRUE(rmi.lookup(oldPk) == 0);
    int64_t newPk = 0;
    ASSERT_TRUE(gl::lookupTemplateKey(((m).templateInterner), ((m).nameMap),
        gl::StrSpan(std::string("(in2[p,marker,3])")), gl::StrSpan("main", 4), newPk));
    ASSERT_TRUE(rmi.lookup(newPk) != 0);
    ASSERT_EQ(rmi.count(), 1);
    const gl::RejectedIntegrationValueSet recs =
        gl::rejectedIntegrationRecordsAt(rmi, newPk, ((m).valueInterner));
    ASSERT_EQ(recs.size(), static_cast<std::size_t>(1));
    const gl::RejectedMapIntegrationValue& v = *recs.begin();

    ASSERT_TRUE(((m).valueInterner).decode(v.sourceExpression) == "(existence0[1,p,3])");


    ASSERT_TRUE(((((m).overallHashMemory)).varsInRejectedMapIntegrationKeys).contains(
        ((m).templateInterner).lookup(gl::StrSpan("p", 1))));
    ASSERT_TRUE(((m).mutatedThisBurst));
    ASSERT_EQ(gl::decodeInternalMailStatements(((m).sameIterationInternalMail),
        ((m).nameMap)).size(), static_cast<std::size_t>(0));

    ASSERT_TRUE(((m).exprOriginMap).empty());
    ASSERT_EQ(v.rewrites.size(), size_t(3));
    ASSERT_EQ(((m).valueInterner).decode(v.rewrites[0]), compound);
    ASSERT_EQ(((m).valueInterner).decode(v.rewrites[1]), std::string("(existence0[1,p,3])"));
    ASSERT_EQ(((m).valueInterner).decode(v.rewrites[2]), std::string("(=[q,p])"));
}
// addInternalMailOrigin's cap policy (the id-form wrapper): below the cap
// append-if-absent; at the cap the existing rows win — a duplicate or any
// newcomer is dropped. Read back through makeHeapMail (id -> string).
TEST(memory, internal_mail_origin_cap_existing_wins) {
    gl::Memory m;
    gl::ColdMail& cm = ((m).sameIterationInternalMail);
    const gl::ExpressionWithValidity k("(h[1])", "main");
    auto line = [](const std::string& tag, const std::string& o,
                   const std::string& v) {
        return gl::OriginLine{ tag, std::vector<gl::ExpressionWithValidity>{
            gl::ExpressionWithValidity(o, v) } };
    };
    // Real OriginTag strings only — addInternalMailOrigin validates the tag via
    // originTagFromString (the closed vocabulary). "disintegration" / "premise"
    // are foundation (non-convenience) tags; "equality1" / "equality2" convenience.
    const int cap = 2;
    gl::addInternalMailOrigin(cm, ((m).originInterner), k, line("disintegration", "p", "main"), cap);
    gl::addInternalMailOrigin(cm, ((m).originInterner), k, line("equality1", "q", "main"), cap);
    gl::addInternalMailOrigin(cm, ((m).originInterner), k, line("disintegration", "p", "main"), cap); // dup
    gl::addInternalMailOrigin(cm, ((m).originInterner), k, line("premise", "r", "main"), cap);
    gl::addInternalMailOrigin(cm, ((m).originInterner), k, line("equality2", "s", "main"), cap); // dropped

    const gl::Mail hm = gl::makeHeapMail(cm, ((m).nameMap), ((m).originInterner));
    auto it = ((hm).exprOriginMap).find(k);
    ASSERT_TRUE(it != ((hm).exprOriginMap).end());
    ASSERT_EQ(static_cast<int>(it->second.size()), 2);
    ASSERT_TRUE(it->second[0].first == "disintegration");
    ASSERT_TRUE(it->second[1].first == "equality1");   // existing rows win
}

// insertInternalStatement span door (L4 statement sink): the StrSpan overload
// deposits byte-identically to the ExpressionWithValidity overload — same
// NameMap mints, same ColdMail statement key + levels. Two independent Memories
// (parallel mint order); compared through makeHeapMail (id -> string).
TEST(memory, internal_mail_statement_span_door_twin) {
    gl::Memory mEwv;
    gl::Memory mSpan;
    const std::string expr = "(in3[it_0_lev_1_2,7,3,plus])";
    const std::string valid = "main_boundary_ordis_((=[2,repl_lev_1_0]))";
    const std::set<int> levels{ 0, 1, 2 };

    gl::insertInternalStatement(((mEwv).sameIterationInternalMail), ((mEwv).nameMap),
        gl::ExpressionWithValidity(expr, valid), levels);
    gl::insertInternalStatement(((mSpan).sameIterationInternalMail), ((mSpan).nameMap),
        gl::StrSpan(expr), gl::StrSpan(valid), levels);

    const gl::Mail hEwv = gl::makeHeapMail(((mEwv).sameIterationInternalMail),
                                           ((mEwv).nameMap), ((mEwv).originInterner));
    const gl::Mail hSpan = gl::makeHeapMail(((mSpan).sameIterationInternalMail),
                                            ((mSpan).nameMap), ((mSpan).originInterner));

    ASSERT_EQ(static_cast<int>(hEwv.statements.size()), 1);
    ASSERT_EQ(static_cast<int>(hSpan.statements.size()),
              static_cast<int>(hEwv.statements.size()));
    const std::pair<gl::ExpressionWithValidity, std::set<int>>& sE =
        *hEwv.statements.begin();
    const std::pair<gl::ExpressionWithValidity, std::set<int>>& sS =
        *hSpan.statements.begin();
    ASSERT_TRUE(sS.first.original == sE.first.original);
    ASSERT_TRUE(sS.first.validityName == sE.first.validityName);
    ASSERT_TRUE(sS.second == sE.second);
    // Concrete deposited content.
    ASSERT_TRUE(sS.first.original == expr);
    ASSERT_TRUE(sS.first.validityName == valid);
    ASSERT_TRUE((sS.second == std::set<int>{ 0, 1, 2 }));
}

// insertInternalStatement levels-run door (C1): the ascending-run overload
// deposits byte-identically to the std::set<int> span overload — same NameMap
// mints, same IntMailStatementKey bytes per id (id-order facet equality ==
// deload-byte equality). Cases: multi-level {1,3,7}, single {0}, EMPTY run,
// and two statements differing only in levels (multiplicity preserved).
TEST(memory, internal_mail_statement_levels_run_door_twin) {
    gl::Memory mSet;
    gl::Memory mRun;
    const std::string expr = "(in3[it_0_lev_1_2,7,3,plus])";
    const std::string expr2 = "(=[2,repl_lev_1_0])";
    const std::string valid = "main";

    const std::set<int> lv137{ 1, 3, 7 };
    const std::set<int> lv0{ 0 };
    const std::set<int> lvEmpty;
    const std::set<int> lv2{ 2 };

    // Set-overload deposits into mSet.
    gl::insertInternalStatement(((mSet).sameIterationInternalMail), ((mSet).nameMap),
        gl::StrSpan(expr), gl::StrSpan(valid), lv137);
    gl::insertInternalStatement(((mSet).sameIterationInternalMail), ((mSet).nameMap),
        gl::StrSpan(expr2), gl::StrSpan(valid), lv0);
    gl::insertInternalStatement(((mSet).sameIterationInternalMail), ((mSet).nameMap),
        gl::StrSpan(expr2), gl::StrSpan(valid), lvEmpty);
    gl::insertInternalStatement(((mSet).sameIterationInternalMail), ((mSet).nameMap),
        gl::StrSpan(expr2), gl::StrSpan(valid), lv2);  // differs only in levels

    // Run-overload deposits into mRun (each run = the set copied to int[],
    // ascending-unique by std::set iteration; the empty case passes nullptr).
    auto depositRun = [&mRun](const std::string& o, const std::string& v,
                              const std::set<int>& s) {
        int buf[8];
        int32_t n = 0;
        for (const int x : s) buf[n++] = x;
        gl::insertInternalStatement(((mRun).sameIterationInternalMail),
            ((mRun).nameMap), gl::StrSpan(o), gl::StrSpan(v),
            n > 0 ? buf : nullptr, n);
    };
    depositRun(expr, valid, lv137);
    depositRun(expr2, valid, lv0);
    depositRun(expr2, valid, lvEmpty);
    depositRun(expr2, valid, lv2);

    // Facet equality: same count, same key bytes per id.
    auto& a = ((mSet).sameIterationInternalMail).statements_;
    auto& b = ((mRun).sameIterationInternalMail).statements_;
    ASSERT_EQ(a.count(), b.count());
    ASSERT_EQ(a.count(), 4);
    for (int32_t i = 1; i <= a.count(); ++i) {
        ASSERT_TRUE(gl::equalSpans(a.inner().decode(i), b.inner().decode(i)));
    }
}

// RejectedValueBlobView (S4 C1): every accessor reads the exact field the
// codec wrote — checked against Codec<RejectedMapValue>::deserialize AND the
// input value, across empty/multi siblings x empty/multi levels x iteration
// 0/>0; copyLevels reproduces the set's ascending contents.
TEST(memory, rejected_value_blob_view_matches_codec) {
    auto check = [](const gl::RejectedMapValue& v) {
        const std::vector<char> blob =
            gl::Codec<gl::RejectedMapValue>::serialize(v);
        const int32_t n = static_cast<int32_t>(blob.size());
        const gl::RejectedValueBlobView view(blob.data(), n);
        const gl::RejectedMapValue back =
            gl::Codec<gl::RejectedMapValue>::deserialize(blob.data(), n);

        ASSERT_EQ(view.sourceExpressionId(), back.sourceExpression);
        ASSERT_EQ(view.sourceExpressionId(), v.sourceExpression);


        ASSERT_EQ(view.iteration(), back.iteration);
        ASSERT_EQ(view.iteration(), v.iteration);



        ASSERT_EQ(view.rewriteCount(),
                  static_cast<int32_t>(back.rewrites.size()));
        ASSERT_EQ(view.rewriteCount(), static_cast<int32_t>(v.rewrites.size()));
        for (int32_t i = 0; i < view.rewriteCount(); ++i) {
            ASSERT_EQ(view.rewriteId(i),
                      back.rewrites[static_cast<std::size_t>(i)]);
            ASSERT_EQ(view.rewriteId(i),
                      v.rewrites[static_cast<std::size_t>(i)]);
        }

        ASSERT_EQ(view.levelCount(), static_cast<int32_t>(back.levels.size()));
        ASSERT_EQ(view.levelCount(), static_cast<int32_t>(v.levels.size()));
        int lv[16];
        view.copyLevels(lv);
        int64_t k = 0;
        for (const int x : v.levels) {
            ASSERT_EQ(lv[k], x);
            ++k;
        }
    };

    // Empty siblings + empty levels, iteration 0.
    check(sourceRecordFixture(11, 22, 0, 33, {}, {}));
    // 3 siblings + levels {0,2,7}, iteration > 0.
    check(sourceRecordFixture(5, 6, 3, 7, { 101, 102, 103 },
                               std::set<int>{ 0, 2, 7 }));
    // Empty siblings + one level.
    check(sourceRecordFixture(1, 2, 9, 4, {}, std::set<int>{ 5 }));
    // One sibling + empty levels, iteration 0.
    check(sourceRecordFixture(8, 9, 0, 10, { 201 }, {}));
}

// RejectedMapValue run-ctor byte-twin: constructing from an ascending-unique
// (const int*, int32_t) run serializes to the SAME Codec bytes as the set
// ctor — the levels MEMBER stays std::set<int> (storage contract), only the
// construction boundary changes. Cases: empty (nullptr, 0), singleton, multi.
TEST(memory, rejected_value_run_ctor_matches_set_ctor) {
    auto twin = [](const std::set<int>& levels,
                   std::vector<int32_t> siblings) {
        int run[8];
        int32_t n = 0;
        for (const int x : levels) run[n++] = x;
        const int* rp = (n > 0) ? run : nullptr;
        const gl::RejectedMapValue viaSet = sourceRecordFixture(5, 6, 3, 7, siblings, levels);
        const gl::RejectedMapValue viaRun = sourceRecordFixture(5, 6, 3, 7, std::move(siblings),
                                          rp, n);
        const std::vector<char> a =
            gl::Codec<gl::RejectedMapValue>::serialize(viaSet);
        const std::vector<char> b =
            gl::Codec<gl::RejectedMapValue>::serialize(viaRun);
        ASSERT_TRUE(a == b);
    };
    twin({}, {});
    twin({ 5 }, { 101 });
    twin({ 1, 4, 9 }, { 101, 102, 103 });
}

// Canonical-run pin (S4 C1): the cold rejectedMap run is STORED canonical
// under DecodedRejectedValueLess (the insertRejectedValue RMW contract), so
// walking recordsAt in run order IS walking the former RejectedValueSet
// snapshot — and the set's dedup is a no-op on a canonical run. Values are
// inserted deliberately shuffled and crafted so decoded order differs from
// insert order (varied renamedExpression bytes; renamed tie split on
// iteration; full tie through siblings split on levels).
TEST(memory, rejected_run_order_matches_decoded_set_oracle) {
    gl::GlobalMemoryManager g;
    g.init(gl::StaticMemoryConfig{ 1 << 20, 1 << 18 });
    gl::LbArena lb(&g);
    gl::DirtyState d = gl::DirtyState::Clean;
    gl::ColdStringTable valTable(&lb, &d);
    gl::ValueInterner vi;
    vi.bind(&valTable);
    gl::TypedColdBlobMap<int64_t, gl::RejectedMapValue> rm(&lb, &d);

    // Mint order deliberately anti-lex so id order != decoded-lex order.
    const int32_t renZZ = vi.encode("zz_ren");
    const int32_t renAA = vi.encode("aa_ren");
    const int32_t renMM = vi.encode("mm_ren");
    const int32_t expr1 = vi.encode("(in3[a,b,c,plus])");
    const int32_t conc1 = vi.encode("(in[b,1])");

    // Decoded order: B("aa",it0) < E("aa",it2,{0,3}) < D("aa",it2,{2})
    //                < C("mm") < A("zz").
    const gl::RejectedMapValue A = sourceRecordFixture(renZZ, expr1, 5, conc1, {},
                                 std::set<int>{ 1 });
    const gl::RejectedMapValue B = sourceRecordFixture(renAA, expr1, 0, conc1, {}, {});
    const gl::RejectedMapValue C = sourceRecordFixture(renMM, expr1, 1, conc1, { conc1 },
                                 std::set<int>{ 4 });
    const gl::RejectedMapValue D = sourceRecordFixture(renAA, expr1, 2, conc1, {},
                                 std::set<int>{ 2 });
    const gl::RejectedMapValue E = sourceRecordFixture(renAA, expr1, 2, conc1, {},
                                 std::set<int>{ 0, 3 });

    const int64_t pk = 42;
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);
    gl::insertRejectedValue(rm, pk, A, vi, tArena);
    gl::insertRejectedValue(rm, pk, D, vi, tArena);
    gl::insertRejectedValue(rm, pk, C, vi, tArena);
    gl::insertRejectedValue(rm, pk, E, vi, tArena);
    gl::insertRejectedValue(rm, pk, B, vi, tArena);

    const int32_t id = rm.lookup(pk);
    ASSERT_TRUE(id != 0);
    const std::vector<gl::RejectedMapValue> run = rm.recordsAt(id);
    const gl::RejectedValueSet oracle = gl::rejectedRecordsAt(rm, pk, vi);

    ASSERT_EQ(run.size(), oracle.size());
    ASSERT_EQ(static_cast<int>(run.size()), 5);
    std::size_t i = 0;
    for (const gl::RejectedMapValue& o : oracle) {
        const gl::RejectedMapValue& r = run[i];
        ASSERT_EQ(r.sourceExpression, o.sourceExpression);

        ASSERT_EQ(r.iteration, o.iteration);

        ASSERT_TRUE(r.rewrites == o.rewrites);
        ASSERT_TRUE(r.levels == o.levels);
        ++i;
    }
    // The crafted decoded order held (first = B, last = A).
    ASSERT_EQ(run[0].sourceExpression, renAA);
    ASSERT_EQ(run[0].iteration, 0);
    ASSERT_EQ(run[4].sourceExpression, renZZ);
}

// insertAdmissionIdsBlob (S6d C7): the id-run door deposits byte-identically to
// the value-form insertAdmissionValue. Same pre-minted ids, both doors → two
// standalone maps on ONE interner; shuffled multi-record key with decoded order
// != insert order, a duplicate insert, and empty key/rem runs. Asserted per-key
// runLen + per-record peekRecordBytes memcmp == 0.
TEST(memory, insert_admission_ids_blob_matches_value_form) {
    gl::GlobalMemoryManager g;
    g.init(gl::StaticMemoryConfig{ 1 << 20, 1 << 18 });
    gl::LbArena lb(&g);
    gl::DirtyState d = gl::DirtyState::Clean;
    gl::ColdStringTable valTable(&lb, &d);
    gl::ValueInterner vi;
    vi.bind(&valTable);
    gl::TypedColdBlobMap<int64_t, gl::AdmissionMapValue> mapV(&lb, &d);
    gl::TypedColdBlobMap<int64_t, gl::AdmissionMapValue> mapB(&lb, &d);
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);

    // Anti-lex mint so id order != decoded-lex order.
    const int32_t k1 = vi.encode("zz_key");
    const int32_t k2 = vi.encode("aa_key");
    const int32_t r1 = vi.encode("mm_rem");
    const int32_t r2 = vi.encode("bb_rem");
    struct Rec { std::vector<int32_t> key; std::vector<int32_t> rem; int depth; int sec; bool flag; bool ordis; };
    const std::vector<Rec> recs = {
        { {k1, k2}, {r1, r2}, 3, 4, false, false },
        { {k2}, {}, 1, 2, true, false },              // empty rem
        { {}, {r2}, 5, 0, false, false },             // empty key
        { {k1}, {r1}, 7, 8, true, false },
        { {k1, k2}, {r1, r2}, 3, 4, false, false },   // duplicate of the first
        { {k1, k2}, {r1, r2}, 3, 4, false, true },    // ordis twin of the first
    };
    const int64_t pk = 42;
    for (const Rec& rc : recs) {
        gl::AdmissionMapValue v(rc.key, rc.rem, rc.depth, rc.sec, rc.flag, rc.ordis);
        gl::insertAdmissionValue(mapV, pk, v, vi, tArena);
        gl::insertAdmissionIdsBlob(mapB, pk, rc.depth, rc.sec, rc.flag,
            rc.key.empty() ? nullptr : rc.key.data(), static_cast<int32_t>(rc.key.size()),
            rc.rem.empty() ? nullptr : rc.rem.data(), static_cast<int32_t>(rc.rem.size()),
            vi, tArena, rc.ordis);
    }
    const int32_t idV = mapV.lookup(pk);
    const int32_t idB = mapB.lookup(pk);
    ASSERT_TRUE(idV != 0 && idB != 0);
    ASSERT_EQ(mapV.runLen(idV), mapB.runLen(idB));
    for (int32_t j = 0; j < mapV.runLen(idV); ++j) {
        int32_t lV = 0, lB = 0;
        const char* pV = mapV.peekRecordBytes(idV, j, lV, tArena);
        const std::vector<char> bufV(pV, pV + lV);
        const char* pB = mapB.peekRecordBytes(idB, j, lB, tArena);
        ASSERT_EQ(lV, lB);
        ASSERT_TRUE(std::memcmp(bufV.data(), pB, static_cast<size_t>(lV)) == 0);
    }
}

// snapshotAdmissionRun (batch3 row 229): the blob-view snapshot reproduces the
// admissionRecordsAt heap-set snapshot field-for-field, in canonical (stored-run
// == comparator) order. Anti-lex mint so decoded order != insert order; shuffled
// multi-record, empty key/rem runs, a duplicate (deduped by the RMW). A
// never-minted key yields count == 0 (defined miss, not a failure).
TEST(memory, snapshot_admission_run_matches_admissionRecordsAt) {
    gl::GlobalMemoryManager g;
    g.init(gl::StaticMemoryConfig{ 1 << 20, 1 << 18 });
    gl::LbArena lb(&g);
    gl::DirtyState d = gl::DirtyState::Clean;
    gl::ColdStringTable valTable(&lb, &d);
    gl::ValueInterner vi;
    vi.bind(&valTable);
    gl::TypedColdBlobMap<int64_t, gl::AdmissionMapValue> m(&lb, &d);
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);

    const int32_t k1 = vi.encode("zz_key");
    const int32_t k2 = vi.encode("aa_key");
    const int32_t r1 = vi.encode("mm_rem");
    const int32_t r2 = vi.encode("bb_rem");
    struct Rec { std::vector<int32_t> key; std::vector<int32_t> rem; int depth; int sec; bool flag; };
    const std::vector<Rec> recs = {
        { {k1, k2}, {r1, r2}, 3, 4, false },
        { {k2}, {}, 1, 2, true },              // empty rem
        { {}, {r2}, 5, 0, false },             // empty key
        { {k1}, {r1}, 7, 8, true },
        { {k1, k2}, {r1, r2}, 3, 4, false },   // duplicate (deduped by RMW)
    };
    const int64_t pk = 42;
    for (const Rec& rc : recs) {
        gl::AdmissionMapValue v(rc.key, rc.rem, rc.depth, rc.sec, rc.flag);
        gl::insertAdmissionValue(m, pk, v, vi, tArena);
    }

    // Oracle: the retained heap-set snapshot in comparator order.
    const gl::AdmissionValueSet oracle = gl::admissionRecordsAt(m, pk, vi);

    const gl::ArenaOffset snapMark = tArena.cursor();
    const gl::AdmissionRunSnapshot snap = gl::snapshotAdmissionRun(m, pk, tArena);
    ASSERT_EQ(snap.count, static_cast<int32_t>(oracle.size()));

    // The stored run is canonical (sorted+deduped under DecodedAdmissionValueLess),
    // so view position i == oracle iteration position i, field for field.
    int32_t i = 0;
    for (const gl::AdmissionMapValue& ov : oracle) {
        const gl::AdmissionValueBlobView& v = snap.views[i];
        ASSERT_EQ(v.depth(), ov.standardMaxAdmissionDepth);
        ASSERT_EQ(v.sec(), ov.standardMaxSecondaryNumber);
        ASSERT_TRUE((v.flagByte() != 0) == ov.flag);
        ASSERT_EQ(v.keyCount(), static_cast<int32_t>(ov.key.size()));
        for (int32_t e = 0; e < v.keyCount(); ++e) ASSERT_EQ(v.keyId(e), ov.key[static_cast<std::size_t>(e)]);
        ASSERT_EQ(v.remCount(), static_cast<int32_t>(ov.remainingArgs.size()));
        for (int32_t r = 0; r < v.remCount(); ++r) ASSERT_EQ(v.remId(r), ov.remainingArgs[static_cast<std::size_t>(r)]);
        ++i;
    }
    tArena.popTo(snapMark);

    // Never-minted key: a defined empty query result.
    const gl::AdmissionRunSnapshot miss = gl::snapshotAdmissionRun(m, 999, tArena);
    ASSERT_EQ(miss.count, 0);
}

// snapshotRejectedRun (row 310): the arena blob-copy snapshot reproduces the
// heap rejectedRecordsAt set field-for-field in canonical run order, and a
// never-minted key is a defined { nullptr, 0 } miss. The literal sibling of
// snapshot_admission_run_matches_admissionRecordsAt.
TEST(memory, snapshot_rejected_run_matches_set) {
    gl::GlobalMemoryManager g;
    g.init(gl::StaticMemoryConfig{ 1 << 20, 1 << 18 });
    gl::LbArena lb(&g);
    gl::DirtyState d = gl::DirtyState::Clean;
    gl::ColdStringTable valTable(&lb, &d);
    gl::ValueInterner vi;
    vi.bind(&valTable);
    gl::TypedColdBlobMap<int64_t, gl::RejectedMapValue> m(&lb, &d);
    gl::ScratchArena& tArena = gl::genScratchArenas().forSlot(
        gl::genScratchArenas().slotCount() - 1);

    const int32_t ren1 = vi.encode("zz_ren");
    const int32_t ren2 = vi.encode("aa_ren");
    const int32_t ex1 = vi.encode("(in3[a,b,c,plus])");
    const int32_t ex2 = vi.encode("(in[b,1])");
    const int32_t cc1 = vi.encode("cc_one");
    const int32_t cc2 = vi.encode("cc_two");
    const int32_t s1 = vi.encode("sib_m");
    const int32_t s2 = vi.encode("sib_b");
    struct Rec { int32_t ren; int32_t ex; int it; int32_t cc;
                 std::vector<int32_t> sib; std::set<int> lv; };
    const std::vector<Rec> recs = {
        { ren1, ex1, 3, cc1, { s1, s2 }, { 0, 2, 5 } },
        { ren2, ex2, 1, cc2, {}, {} },                  // empty siblings + levels
        { ren1, ex2, 7, cc1, { s2 }, { 1 } },
        { ren1, ex1, 3, cc1, { s1, s2 }, { 0, 2, 5 } }, // duplicate (RMW dedups)
    };
    const int64_t pk = 42;
    for (const Rec& rc : recs) {
        gl::RejectedMapValue v = sourceRecordFixture(rc.ren, rc.ex, rc.it, rc.cc, rc.sib, rc.lv);
        gl::insertRejectedValue(m, pk, v, vi, tArena);
    }

    // Oracle: the retained heap-set snapshot in comparator order.
    const gl::RejectedValueSet oracle = gl::rejectedRecordsAt(m, pk, vi);

    const gl::ArenaOffset snapMark = tArena.cursor();
    const gl::RejectedRunSnapshot snap = gl::snapshotRejectedRun(m, pk, tArena);
    ASSERT_EQ(snap.count, static_cast<int32_t>(oracle.size()));

    int32_t i = 0;
    for (const gl::RejectedMapValue& ov : oracle) {
        const gl::RejectedValueBlobView& v = snap.views[i];
        ASSERT_EQ(v.sourceExpressionId(), ov.sourceExpression);

        ASSERT_EQ(v.iteration(), ov.iteration);

        ASSERT_EQ(v.rewriteCount(), static_cast<int32_t>(ov.rewrites.size()));
        for (int32_t e = 0; e < v.rewriteCount(); ++e)
            ASSERT_EQ(v.rewriteId(e), ov.rewrites[static_cast<std::size_t>(e)]);
        ASSERT_EQ(v.levelCount(), static_cast<int32_t>(ov.levels.size()));
        int32_t li = 0;
        for (const int lv : ov.levels) { ASSERT_EQ(v.levelAt(li), lv); ++li; }
        ++i;
    }
    tArena.popTo(snapMark);

    const gl::RejectedRunSnapshot miss = gl::snapshotRejectedRun(m, 999, tArena);
    ASSERT_EQ(miss.count, 0);
}

