// add_origin_id cold POD overload: raw (tag, deps) fields write runs
// byte-identical to the IdOrigin cold overload across the full D-49 battery.
TEST(memory, add_origin_id_cold_pod_matches_idorigin) {
    gl::GlobalMemoryManager g;
    g.init(gl::StaticMemoryConfig{ 1 << 20, 1 << 18 });
    gl::LbArena lb(&g);
    gl::DirtyState d = gl::DirtyState::Clean;
    gl::TypedColdBlobMap<int64_t, gl::IdOrigin> mapNew(&lb, &d);
    gl::TypedColdBlobMap<int64_t, gl::IdOrigin> mapOracle(&lb, &d);
    const int64_t key = 88;
    const int cap = 3;

    const auto sameRun = [&]() -> bool {
        const int32_t ni = mapNew.lookup(key);
        const int32_t oi = mapOracle.lookup(key);
        if ((ni != 0) != (oi != 0)) return false;
        if (ni == 0) return true;
        if (mapNew.runLen(ni) != mapOracle.runLen(oi)) return false;
        std::vector<char> sn, so;
        for (int32_t j = 0; j < mapNew.runLen(ni); ++j) {
            int32_t ln = 0, lo = 0;
            const char* pn = mapNew.peekRecordBytes(ni, j, ln, sn);
            const std::vector<char> bn(pn, pn + ln);
            const char* po = mapOracle.peekRecordBytes(oi, j, lo, so);
            if (ln != lo) return false;
            if (std::memcmp(bn.data(), po, static_cast<std::size_t>(ln)) != 0)
                return false;
        }
        return true;
    };
    const auto step = [&](const gl::IdOrigin& r) {
        gl::addOriginId(mapNew, key, static_cast<uint8_t>(r.first),
            r.second.empty() ? nullptr : r.second.data(),
            static_cast<int32_t>(r.second.size()), cap);
        gl::addOriginId(mapOracle, key, r, cap);
        ASSERT_TRUE(sameRun());
    };

    step(gl::IdOrigin(gl::OriginTag::disintegration, { 1, 2 }));
    step(gl::IdOrigin(gl::OriginTag::equality1, { 3 }));
    step(gl::IdOrigin(gl::OriginTag::disintegration, { 1, 2 }));  // dup
    step(gl::IdOrigin(gl::OriginTag::theorem, {}));               // reach cap
    step(gl::IdOrigin(gl::OriginTag::premise, { 4, 5, 6 }));      // dropped (existing wins)
    step(gl::IdOrigin(gl::OriginTag::equality2, { 9 }));          // conv -> existing wins
    step(gl::IdOrigin(gl::OriginTag::premise, { 4, 5, 6 }));      // cap-full dup
    step(gl::IdOrigin(gl::OriginTag::broadcast, { 7 }));          // no conv slot left
}

// OriginAbsorbBatch: staging a bulk merge's lines and writing them — by the
// rebuild, by the one-by-one splices, or by whichever apply() chooses — leaves
// the cold origin map (key ids, runs, bytes) and the origin interner exactly
// as the same addOriginId / addOriginEncoded calls made one by one: duplicates
// of stored and of staged lines, the cap reached by stored and by staged
// lines, new keys minted in first-acceptance order, a key whose only line is
// rejected, span-keyed lines, an empty batch.
TEST(memory, origin_absorb_batch_matches_one_by_one_add_origin) {
    const int cap = 3;
    struct Line { int64_t key; gl::OriginTag tag; int64_t deps[3]; int32_t depN; };
    const Line seedLines[] = {
        { 10, gl::OriginTag::disintegration, { 1, 2 }, 2 },
        { 10, gl::OriginTag::equality1, { 3 }, 1 },
        { 20, gl::OriginTag::disintegration, { 2 }, 1 },
        { 30, gl::OriginTag::theorem, { 0 }, 0 },
        { 30, gl::OriginTag::premise, { 4 }, 1 },
        { 30, gl::OriginTag::equality2, { 5, 6 }, 2 },
        { 40, gl::OriginTag::expansion, { 8 }, 1 } };
    const Line lines[] = {
        { 20, gl::OriginTag::equality1, { 5 }, 1 },          // new line on a stored key
        { 20, gl::OriginTag::equality1, { 5 }, 1 },          // duplicate of a staged line
        { 20, gl::OriginTag::disintegration, { 2 }, 1 },     // duplicate of a stored line
        { 99, gl::OriginTag::theorem, { 0 }, 0 },            // new key
        { 99, gl::OriginTag::premise, { 7, 8 }, 2 },         // second line of the new key
        { 99, gl::OriginTag::theorem, { 0 }, 0 },            // duplicate on the new key
        { 30, gl::OriginTag::premise, { 9 }, 1 },            // stored cap full: dropped
        { 10, gl::OriginTag::goal, { 0 }, 0 },               // fills key 10 to the cap
        { 10, gl::OriginTag::broadcast, { 3 }, 1 },          // cap reached by a staged line
        { 40, gl::OriginTag::expansion, { 8 }, 1 },          // only a duplicate: untouched
        { 77, gl::OriginTag::equality2, { 1, 2, 3 }, 3 } };  // second new key
    const std::string kO = "(=[x,y])", kV = "main", k2O = "(p[z])", k2V = "s1";
    const std::string dO = "(in[x,1])", dV = "main";
    const gl::OriginDep deps1[1] = { { gl::StrSpan(dO), gl::StrSpan(dV) } };
    const auto addOne = [&](gl::Memory& m, const Line& l) {
        gl::addOriginId(((m).exprOriginMap), l.key, static_cast<uint8_t>(l.tag),
            l.depN > 0 ? l.deps : nullptr, l.depN, cap);
    };

    // The oracle: every line written one by one. Span-keyed lines: each key's
    // lines are consecutive, as in the bulk merge (one row per key); the
    // repeat of each line is a duplicate.
    gl::Memory oneByOne;
    for (const Line& l : seedLines) addOne(oneByOne, l);
    for (const Line& l : lines) addOne(oneByOne, l);
    for (int repeat = 0; repeat < 2; ++repeat)
        gl::addOriginEncoded(((oneByOne).exprOriginMap), ((oneByOne).originInterner),
            gl::StrSpan(kO), gl::StrSpan(kV), gl::OriginTag::expansion, deps1, 1, cap);
    for (int repeat = 0; repeat < 2; ++repeat)
        gl::addOriginEncoded(((oneByOne).exprOriginMap), ((oneByOne).originInterner),
            gl::StrSpan(k2O), gl::StrSpan(k2V), gl::OriginTag::goal, nullptr, 0, cap);

    gl::ScratchArena& arena = gl::genScratchArenas().forSlot(0);
    // Mode 0: writeByRebuild, 1: writeOneByOne, 2: apply (its own choice).
    for (int mode = 0; mode < 3; ++mode) {
        gl::Memory batched;
        for (const Line& l : seedLines) addOne(batched, l);
        const auto write = [&](gl::OriginAbsorbBatch& batch) {
            if (mode == 0) batch.writeByRebuild();
            else if (mode == 1) batch.writeOneByOne();
            else batch.apply();
        };
        {
            gl::OriginAbsorbBatch batch(((batched).exprOriginMap), arena);
            batch.apply();  // an empty batch changes nothing
            ASSERT_EQ(((batched).exprOriginMap).count(), 4);
            for (const Line& l : lines)
                batch.add(l.key, static_cast<uint8_t>(l.tag),
                    l.depN > 0 ? l.deps : nullptr, l.depN, cap);
            ASSERT_EQ(((batched).exprOriginMap).count(), 4);  // staging writes nothing
            ASSERT_EQ(((batched).exprOriginMap).runLen(((batched).exprOriginMap).lookup(20)), 1);
            write(batch);
        }
        {
            gl::OriginAbsorbBatch batch(((batched).exprOriginMap), arena);
            for (int repeat = 0; repeat < 2; ++repeat)
                batch.addEncoded(((batched).originInterner), gl::StrSpan(kO), gl::StrSpan(kV),
                    gl::OriginTag::expansion, deps1, 1, cap);
            for (int repeat = 0; repeat < 2; ++repeat)
                batch.addEncoded(((batched).originInterner), gl::StrSpan(k2O), gl::StrSpan(k2V),
                    gl::OriginTag::goal, nullptr, 0, cap);
            write(batch);
        }

        // Same keys in the same id order, same runs byte for byte.
        auto& a = ((oneByOne).exprOriginMap);
        auto& b = ((batched).exprOriginMap);
        ASSERT_EQ(a.count(), b.count());
        std::vector<char> sa, sb;
        for (int32_t id = 1; id <= a.count(); ++id) {
            ASSERT_EQ(a.decodeKey(id), b.decodeKey(id));
            ASSERT_EQ(a.runLen(id), b.runLen(id));
            for (int32_t j = 0; j < a.runLen(id); ++j) {
                int32_t la = 0, lb = 0;
                const char* pa = a.peekRecordBytes(id, j, la, sa);
                const std::vector<char> copyA(pa, pa + la);
                const char* pb = b.peekRecordBytes(id, j, lb, sb);
                ASSERT_EQ(la, lb);
                ASSERT_TRUE(std::memcmp(copyA.data(), pb, static_cast<std::size_t>(la)) == 0);
            }
        }
        // Keys 99 and 77 were minted in staging order after the four stored keys.
        ASSERT_EQ(b.decodeKey(5), static_cast<int64_t>(99));
        ASSERT_EQ(b.decodeKey(6), static_cast<int64_t>(77));
        ASSERT_EQ(b.runLen(b.lookup(10)), 3);
        ASSERT_EQ(b.runLen(b.lookup(99)), 2);
        ASSERT_EQ(b.count(), 8);
    }
}

// OriginAbsorbBatch::rebuildPays: on a map of 2,000 one-line keys a single
// added line, or lines of new keys only, keep the splices; lines added to the
// first half of the keys make the one rebuild cheaper. Either way apply()
// writes what the one-by-one writes do.
TEST(memory, origin_absorb_batch_rebuild_pays_for_large_merges_only) {
    const int cap = 4;
    gl::Memory oracle, batched;
    for (int64_t k = 1; k <= 2000; ++k) {
        const int64_t dep[1] = { k };
        gl::addOriginId(((oracle).exprOriginMap), k, static_cast<uint8_t>(gl::OriginTag::theorem), dep, 1, cap);
        gl::addOriginId(((batched).exprOriginMap), k, static_cast<uint8_t>(gl::OriginTag::theorem), dep, 1, cap);
    }
    gl::ScratchArena& arena = gl::genScratchArenas().forSlot(0);
    const int64_t newDep[1] = { 7 };
    {
        gl::OriginAbsorbBatch one(((batched).exprOriginMap), arena);
        one.add(1, static_cast<uint8_t>(gl::OriginTag::premise), newDep, 1, cap);
        ASSERT_TRUE(!one.rebuildPays());
    }
    {
        gl::OriginAbsorbBatch fresh(((batched).exprOriginMap), arena);
        for (int64_t k = 3001; k <= 3100; ++k)
            fresh.add(k, static_cast<uint8_t>(gl::OriginTag::premise), newDep, 1, cap);
        ASSERT_TRUE(!fresh.rebuildPays());
    }
    {
        gl::OriginAbsorbBatch many(((batched).exprOriginMap), arena);
        for (int64_t k = 1; k <= 1000; ++k)
            many.add(k, static_cast<uint8_t>(gl::OriginTag::premise), newDep, 1, cap);
        ASSERT_TRUE(many.rebuildPays());
        many.apply();
    }
    for (int64_t k = 1; k <= 1000; ++k)
        gl::addOriginId(((oracle).exprOriginMap), k, static_cast<uint8_t>(gl::OriginTag::premise), newDep, 1, cap);
    auto& a = ((oracle).exprOriginMap);
    auto& b = ((batched).exprOriginMap);
    ASSERT_EQ(a.count(), b.count());
    std::vector<char> sa, sb;
    for (int32_t id = 1; id <= a.count(); ++id) {
        ASSERT_EQ(a.decodeKey(id), b.decodeKey(id));
        ASSERT_EQ(a.runLen(id), b.runLen(id));
        for (int32_t j = 0; j < a.runLen(id); ++j) {
            int32_t la = 0, lb = 0;
            const char* pa = a.peekRecordBytes(id, j, la, sa);
            const std::vector<char> copyA(pa, pa + la);
            const char* pb = b.peekRecordBytes(id, j, lb, sb);
            ASSERT_EQ(la, lb);
            ASSERT_TRUE(std::memcmp(copyA.data(), pb, static_cast<std::size_t>(la)) == 0);
        }
    }
}

