namespace {
    // An implication subproof below main with one OR case of its own:
    // main > subproof (implication5[4,5]) > case of (or95[6,7]).
    struct InnermostGoalScopes {
        gl::NameId subproof, subproofCase;
        int32_t cohort;
        explicit InnermostGoalScopes(Phase3OrExclusionFixture& f,
                                     const std::string& payload = "(implication5[4,5])") {
            subproof = f.push(f.mainId, payload);
            subproofCase = f.push(subproof, "ordis_(or95[6,7])_((in[6,7]))");
            const std::string parent = ((f.memory).nameMap).decode(subproof);
            cohort = gl::mintOrCohortId(((f.memory).lbStateInterner),
                ((f.memory).lbStateInterner).encode(gl::StrSpan(parent)),
                ((f.memory).lbStateInterner).encode(gl::StrSpan("(or95[6,7])", 11)));
            ((f.memory).orDisjunctCount).insert(cohort, 2);
        }
    };
}

// The innermost goal scope is the deepest scope on the chain holding a goal;
// goals at descendant or sibling scopes are never on the chain.
TEST(prover, innermost_goal_scope_is_the_deepest_goal_holding_scope) {
    Phase3OrExclusionFixture f;
    InnermostGoalScopes s(f);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, s.subproofCase), 0);
    f.goal("(in[6,7])", f.child);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, f.branch), 0);
    f.goal("(in[1,2])", f.mainId);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, s.subproofCase), f.mainId);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, f.branch), f.mainId);
    f.goal("(in[8,9])", s.subproof);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, s.subproofCase), s.subproof);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, s.subproof), s.subproof);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, f.branch), f.mainId);
    ASSERT_EQ(gl::StatementKnowledge::innermostGoalScope(f.memory, f.child), f.child);
}

// A case inside a subproof resolves on the subproof's goal alone: main's open
// goal is shadowed for it, but still decides the case directly under main.
TEST(prover, case_in_a_subproof_resolves_on_the_subproof_goal_alone) {
    Phase3OrExclusionFixture f;
    InnermostGoalScopes s(f);
    f.goal("(in[1,2])", f.mainId);
    f.goal("(in[8,9])", s.subproof);
    ASSERT_FALSE(gl::tests::CaseProcessorFixture::orBranchGoalsResolved(f.analyzer.caseProcessor, f.memory, s.subproofCase));
    f.known("(in[8,9])", s.subproofCase);
    ASSERT_TRUE(gl::tests::CaseProcessorFixture::orBranchGoalsResolved(f.analyzer.caseProcessor, f.memory, s.subproofCase));
    ASSERT_FALSE(gl::tests::CaseProcessorFixture::orBranchGoalsResolved(f.analyzer.caseProcessor, f.memory, f.branch));
    ((f.memory).orLiveBranches).mint(s.subproofCase);
    f.analyzer.caseProcessor.freezeResolvedOrBranches(f.memory);
    ASSERT_TRUE(((f.memory).frozenOrBranches).contains(s.subproofCase));
    ASSERT_TRUE(((f.memory).pendingWipeScopes).contains(s.subproofCase));
}

// In an active primed contradiction block a closer explicit goal shadows the
// implicit contradiction goal of main; without one the case stays open.
TEST(prover, primed_implicit_goal_is_shadowed_by_a_closer_goal) {
    Phase3OrExclusionFixture f;
    ((f.memory).primedForContradiction) = true;
    InnermostGoalScopes s(f);
    f.goal("(in[8,9])", s.subproof);
    f.known("(in[8,9])", s.subproofCase);
    ASSERT_TRUE(gl::tests::CaseProcessorFixture::orBranchGoalsResolved(f.analyzer.caseProcessor, f.memory, s.subproofCase));
    ASSERT_FALSE(gl::tests::CaseProcessorFixture::orBranchGoalsResolved(f.analyzer.caseProcessor, f.memory, f.branch));
}

// The release probe of a refused deposit stages the cohort only for a goal of
// the innermost goal scope; a shadowed main goal releases nothing.
TEST(prover, refused_deposit_release_probe_uses_the_innermost_goal_scope) {
    for (bool subproofGoal : { false, true }) {
        Phase3OrExclusionFixture f;
        InnermostGoalScopes s(f);
        const gl::NameId mainGoal = f.goal("(in[1,2])", f.mainId);
        const gl::NameId subGoal = f.goal("(in[8,9])", s.subproof);
        ((f.memory).orPendingBranches).insertSorted(s.cohort,
            ((f.memory).lbStateInterner).encode(gl::StrSpan("((in[7,6]))", 11)),
            gl::DecodedIdLess{&((f.memory).lbStateInterner)});
        f.analyzer.caseProcessor.stageOrReleaseForRefusedDeposit(f.memory,
            subproofGoal ? subGoal : mainGoal, s.subproofCase);
        ASSERT_EQ(((f.memory).pendingOrReleases).lookup(s.cohort) != 0, subproofGoal);
    }
}

// A live case holding the negation of its implication subproof's goal retires
// the subproof and leaves the live registry; nothing happens in a primed
// block, for a goal of main, for an integration subproof or without the
// negation.
TEST(prover, refuted_goal_case_retires_its_implication_subproof) {
    {
        Phase3OrExclusionFixture f;
        InnermostGoalScopes s(f);
        f.goal("(in[8,9])", s.subproof);
        ((f.memory).orLiveBranches).mint(s.subproofCase);
        ((f.memory).orLiveBranches).mint(f.branch);
        f.analyzer.caseProcessor.retireRefutedGoalSubproofs(f.memory);
        ASSERT_EQ(((f.memory).pendingWipeScopes).count(), 0);
        f.known("!(in[8,9])", s.subproofCase);
        f.analyzer.caseProcessor.retireRefutedGoalSubproofs(f.memory);
        ASSERT_TRUE(((f.memory).pendingWipeScopes).contains(s.subproof));
        ASSERT_EQ(((f.memory).orLiveBranches).lookup(s.subproofCase), 0);
        ASSERT_TRUE(((f.memory).orLiveBranches).lookup(f.branch) != 0);
    }
    {
        Phase3OrExclusionFixture f;
        ((f.memory).primedForContradiction) = true;
        InnermostGoalScopes s(f);
        f.goal("(in[8,9])", s.subproof);
        ((f.memory).orLiveBranches).mint(s.subproofCase);
        f.known("!(in[8,9])", s.subproofCase);
        f.analyzer.caseProcessor.retireRefutedGoalSubproofs(f.memory);
        ASSERT_EQ(((f.memory).pendingWipeScopes).count(), 0);
    }
    {
        Phase3OrExclusionFixture f;
        f.goal("(in[8,9])", f.mainId);
        ((f.memory).orLiveBranches).mint(f.branch);
        f.known("!(in[8,9])", f.branch);
        f.analyzer.caseProcessor.retireRefutedGoalSubproofs(f.memory);
        ASSERT_EQ(((f.memory).pendingWipeScopes).count(), 0);
    }
    {
        Phase3OrExclusionFixture f;
        InnermostGoalScopes s(f, "(sequence[1,4,2,9,10])");
        f.goal("(in[8,9])", s.subproof);
        ((f.memory).orLiveBranches).mint(s.subproofCase);
        f.known("!(in[8,9])", s.subproofCase);
        f.analyzer.caseProcessor.retireRefutedGoalSubproofs(f.memory);
        ASSERT_EQ(((f.memory).pendingWipeScopes).count(), 0);
    }
}

// Goals may live only at main, subproofs (bare or goal-qualified) and
// OR-integration scopes.
TEST(prover, goal_scopes_are_main_subproofs_and_or_integrations) {
    Phase3OrExclusionFixture f;
    const auto& names = (f.memory).nameMap;
    ASSERT_TRUE(gl::ScopeSyntax::canHoldGoal(names, f.mainId));
    ASSERT_TRUE(gl::ScopeSyntax::canHoldGoal(names, f.push(f.mainId, "(implication5[4,5])")));
    ASSERT_TRUE(gl::ScopeSyntax::canHoldGoal(names,
        f.push(f.mainId, "(in[1,2])_subproof_(implication5[4,5])")));
    ASSERT_TRUE(gl::ScopeSyntax::canHoldGoal(names, f.push(f.mainId, "orint_(or94[4,5])_((in[4,5]))")));
    ASSERT_FALSE(gl::ScopeSyntax::canHoldGoal(names, f.branch));
    ASSERT_FALSE(gl::ScopeSyntax::canHoldGoal(names, f.child));
    ASSERT_FALSE(gl::ScopeSyntax::canHoldGoal(names, f.push(f.mainId, "contradiction_(in[1,2])")));
    ASSERT_FALSE(gl::ScopeSyntax::canHoldGoal(names, f.push(f.mainId, "is_(in2[marker,2,3])_7")));
}

TEST(prover, contradiction_case_refutation_survives_both_mail_directions) {
    for (bool postBurst : { false, true }) {
        Phase3OrExclusionFixture f;
        ((f.memory).primedForContradiction) = true;
        f.known("!(in[9,1])", f.mainId);
        gl::ColdMail& input = postBurst ? ((f.memory).sameIterationInternalMail)
                                       : ((f.memory).nextIterationInternalMail);
        gl::ColdMail& output = postBurst ? ((f.memory).nextIterationInternalMail)
                                        : ((f.memory).sameIterationInternalMail);
        const std::string branch = ((f.memory).nameMap).decode(f.branch);
        const int levels[] = { 0 };
        gl::insertInternalStatement(input, ((f.memory).nameMap),
            gl::StrSpan("(in[9,1])", 9), gl::StrSpan(branch), levels, 1);
        gl::addInternalMailOrigin(input, ((f.memory).originInterner),
            gl::StrSpan("(in[9,1])", 9), gl::StrSpan(branch),
            gl::OriginTag::taskFormulation, nullptr, 0, 8);
        f.analyzer.logicBlockOperations.standardProcessing(f.memory, nullptr, input, output, -1);
        ASSERT_TRUE(input.empty());
        ASSERT_TRUE(((f.memory).isActive));
        bool queued = false, history = false;
        for (const auto& row : gl::decodeInternalMailStatements(output, ((f.memory).nameMap)))
            if (row.first.original == "!(in[4,5])" && row.first.validityName == "main") {
                queued = true;
                ASSERT_EQ(row.second, (std::set<int>{0}));
            }
        for (const auto& row : gl::decodeInternalMailOrigins(output, ((f.memory).originInterner)))
            if (row.first.original == "!(in[4,5])" && row.first.validityName == "main")
                for (const auto& origin : row.second)
                    if (origin.first == "contradiction") {
                        history = true;
                        ASSERT_EQ(origin.second.size(), static_cast<std::size_t>(2));
                    }
        ASSERT_TRUE(queued);
        ASSERT_TRUE(history);
        f.analyzer.logicBlockOperations.standardProcessing(f.memory, nullptr, output, input, -1);
        ASSERT_TRUE(f.has("!(in[4,5])", f.mainId));
        ASSERT_TRUE(((f.memory).isActive));
    }
}

